import { allocationBudget, allocationSpent, allocationStatus, answerBudgetQuestion, autoPostDueRecurring, categoryColors, createEmptyAppData, createFamilyCode, expenseCategories, financialBalance, formatDate, inPlanPeriod, isoToday, newId, normalizeAppData, parseNaturalSpendScenario, parseRomanianAmount, pendingRecurringInPlan, planEndDate, planForecast, recordDebtPayment, savingSuggestions, sourceBalance, type AppData, type BudgetAllocation, type Debt, type PaymentKind, type Receipt, type ReceiptLine, type SavingsGoal, type Transaction, type TransactionKind } from "@/lib/finance-data";
import { decryptFamilyData, encryptFamilyData, getRemotePackage, mergeFamilyData, saveRemotePackage } from "@/lib/github-sync";

type MainView = "home" | "journal" | "plan" | "objectives" | "more";
type MoreView = "overview" | "debts" | "savings" | "receipts" | "recurring" | "reports" | "assistant" | "settings" | "sync" | "guide";
type ThemeId = "ivory" | "forest" | "midnight" | "copper";
const themeOptions: Array<{ id: ThemeId; name: string; detail: string; swatches: [string, string, string] }> = [
  { id: "ivory", name: "Ivory Ledger", detail: "Lumină caldă, verde de atelier și accente de miere.", swatches: ["#f7f5ef", "#1b5749", "#eec64d"] },
  { id: "forest", name: "Forest Night", detail: "Verde nocturn pentru lectura liniștită de seară.", swatches: ["#081e19", "#1b5b4c", "#efd079"] },
  { id: "midnight", name: "Black–Blue", detail: "Negru-albăstrui cu albastru electric controlat.", swatches: ["#050914", "#102448", "#5da8ff"] },
  { id: "copper", name: "Ink–Copper", detail: "Grafit dens, cupru cald și date accentuate discret.", swatches: ["#131210", "#3a3028", "#d38d59"] },
];
const STORE_KEY = "buget-familie:app-data-v6";
const LEGACY_KEY = "buget-familie:app-data-v3";
const fmt = new Intl.NumberFormat("ro-RO", { style: "currency", currency: "RON", maximumFractionDigits: 0 });
const fmtExact = new Intl.NumberFormat("ro-RO", { style: "currency", currency: "RON", minimumFractionDigits: 2, maximumFractionDigits: 2 });
const ReportsPanel = lazy(() => import("@/components/ReportsPanel").then((module) => ({ default: module.ReportsPanel })));
const RecurringPanel = lazy(() => import("@/components/RecurringPanel").then((module) => ({ default: module.RecurringPanel })));
const AdvisorPanel = lazy(() => import("@/components/AdvisorPanel").then((module) => ({ default: module.AdvisorPanel })));

const money = (value: number) => fmt.format(Number.isFinite(value) ? value : 0);
const dateText = (value: string, full = false) => formatDate(value, full ? { day: "2-digit", month: "long", year: "numeric" } : { day: "2-digit", month: "short" });
const sourceKindName: Record<PaymentKind, string> = { card: "Card", cash: "Cash", meal: "Bonuri de masă", transfer: "Transfer" };
type AdvisorAction = "plan" | "recurring" | "objectives" | "journal";
type AdvisorSignal = { id: string; tone: "good" | "watch" | "risk"; eyebrow: string; title: string; detail: string; action: AdvisorAction; actionLabel: string };

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="bf-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="bf-modal" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(event) => event.stopPropagation()}><header><div><p className="bf-kicker">ÎNREGISTRARE RAPIDĂ</p><h2>{title}</h2></div><button className="bf-icon-button" aria-label="Închide" onClick={onClose}><X size={19} /></button></header>{children}</section></div>;
}

function ThemePicker({ theme, onChange, onClose }: { theme: ThemeId; onChange: (theme: ThemeId) => void; onClose: () => void }) {
  return <div className="bf-modal-backdrop bf-theme-backdrop" role="presentation" onMouseDown={onClose}><section className="bf-modal bf-theme-picker" role="dialog" aria-modal="true" aria-label="Alege aspectul" onMouseDown={(event) => event.stopPropagation()}><header><div><p className="bf-kicker">ASPECTUL APLICAȚIEI</p><h2>Alege materialul care îți este mai ușor de citit.</h2></div><button className="bf-icon-button" aria-label="Închide alegerea temei" onClick={onClose}><X size={19} /></button></header><p className="bf-theme-picker-intro">Semnificația rămâne neschimbată: veniturile, cheltuielile, alertele și plicurile se citesc la fel în fiecare temă.</p><div className="bf-theme-grid">{themeOptions.map((option) => <button key={option.id} className={`bf-theme-option ${option.id} ${theme === option.id ? "selected" : ""}`} aria-pressed={theme === option.id} onClick={() => { onChange(option.id); onClose(); }}><span className="bf-theme-swatch" style={{ background: `linear-gradient(135deg, ${option.swatches[0]} 0 52%, ${option.swatches[1]} 52% 77%, ${option.swatches[2]} 77%)` }} /><span><b>{option.name}</b><small>{option.detail}</small></span><i>{theme === option.id && <Check size={14} />}</i></button>)}</div></section></div>;
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="bf-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

function TransactionForm({ data, initial, onSave, onClose }: { data: AppData; initial?: Transaction; onSave: (item: Transaction) => void; onClose: () => void }) {
  const [kind, setKind] = useState<TransactionKind>(initial?.kind || "expense");
  const [title, setTitle] = useState(initial?.title || "");
  const [amount, setAmount] = useState(initial ? String(initial.amount) : "");
  const [date, setDate] = useState(initial?.date || isoToday());
  const [memberId, setMemberId] = useState(initial?.memberId || data.settings.members.find((member) => member.name === initial?.person)?.id || data.settings.members[0]?.id || "");
  const [sourceId, setSourceId] = useState(initial?.sourceId || data.settings.paymentSources.find((source) => source.name === initial?.source)?.id || data.settings.paymentSources[0]?.id || "");
  const [category, setCategory] = useState(initial?.category || "Alimente");
  const [allocationId, setAllocationId] = useState(initial?.allocationId || "outside");
  const [note, setNote] = useState(initial?.note || "");
  const [error, setError] = useState(""); const envelopeCandidates = kind === "expense" ? data.settings.salaryPlan.allocations.filter((allocation) => allocation.category === category && (!allocation.sourceId || allocation.sourceId === sourceId) && (!allocation.memberId || allocation.memberId === memberId)) : []; const matchedEnvelope = allocationId === "outside" ? undefined : envelopeCandidates.find((allocation) => allocation.id === allocationId); const sourceOwner = (source: AppData["settings"]["paymentSources"][number]) => data.settings.members.find((member) => member.id === source.memberId)?.name || "Comun"; const allocationMember = matchedEnvelope ? data.settings.members.find((member) => member.id === matchedEnvelope.memberId)?.name || "Comun" : ""; const editedAlreadyInEnvelope = Boolean(matchedEnvelope && initial?.id && initial.allocationId === matchedEnvelope.id); const envelopeSpent = matchedEnvelope ? Math.max(0, allocationSpent(data, matchedEnvelope) - (editedAlreadyInEnvelope ? initial?.amount || 0 : 0)) : 0; const envelopeRemaining = matchedEnvelope ? allocationBudget(data, matchedEnvelope) - envelopeSpent : 0; const proposedAmount = parseRomanianAmount(amount); const envelopeAfter = envelopeRemaining - proposedAmount;
  useEffect(() => { if (kind !== "expense" || (allocationId !== "outside" && !envelopeCandidates.some((allocation) => allocation.id === allocationId))) setAllocationId("outside"); }, [kind, category, memberId, sourceId, allocationId, envelopeCandidates]);
  const save = () => {
    const numeric = parseRomanianAmount(amount);
    const source = data.settings.paymentSources.find((item) => item.id === sourceId);
    const member = data.settings.members.find((item) => item.id === memberId);
    if (!title.trim()) return setError("Scrie o denumire pentru mișcare.");
    if (!numeric || numeric <= 0) return setError("Introdu o sumă mai mare decât zero.");
    if (!source || !member || !date) return setError("Alege data, membrul și sursa de plată.");
    if (kind === "expense" && allocationId !== "outside" && !matchedEnvelope) return setError("Plicul ales nu mai corespunde categoriei, membrului sau sursei. Alege din nou.");
    onSave({ id: initial?.id || newId("tx"), title: title.trim(), amount: numeric, kind, category: kind === "income" ? "Venit" : category, sourceId: source.id, source: source.name, memberId: member.id, person: member.name, date, note: note.trim() || undefined, allocationId: kind === "expense" ? allocationId : undefined, createdAt: initial?.createdAt || new Date().toISOString(), receiptId: initial?.receiptId });
    onClose();
  };
  return <Modal title={initial ? "Corectează mișcarea" : "Adaugă mișcare"} onClose={onClose}><div className="bf-segment"><button className={kind === "expense" ? "active expense" : ""} onClick={() => setKind("expense")}>Cheltuială</button><button className={kind === "income" ? "active income" : ""} onClick={() => setKind("income")}>Venit</button></div><div className="bf-form-grid"><Field label="Denumire"><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="ex. Cumpărături Lidl" /></Field><Field label="Sumă (lei)"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></Field><Field label="Data"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Cine a făcut mișcarea"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label={kind === "income" ? "Încasat în" : "Plătit din (sursa reală)"}><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {sourceOwner(source)} · {money(sourceBalance(data, source.id))}</option>)}</select></Field>{kind === "expense" && <Field label="Categorie"><select value={category} onChange={(event) => setCategory(event.target.value)}>{[...expenseCategories, ...data.settings.customCategories].map((item) => <option key={item}>{item}</option>)}</select></Field>}</div>{kind === "expense" && <section className="bf-envelope-choice"><div><p className="bf-kicker">BUGET REPARTIZAT (OPȚIONAL)</p><h3>Din ce plic plătești?</h3><p>Alegi plicul care trebuie consumat. Plata rămâne mereu în sursa selectată mai sus.</p></div><Field label="Plic de consum"><select value={allocationId} onChange={(event) => setAllocationId(event.target.value)}><option value="outside">În afara plicurilor — nu consumă buget repartizat</option>{envelopeCandidates.map((allocation) => { const owner = data.settings.members.find((member) => member.id === allocation.memberId)?.name || "Comun"; const source = data.settings.paymentSources.find((item) => item.id === allocation.sourceId); const remaining = Math.max(0, allocationBudget(data, allocation) - allocationSpent(data, allocation)); return <option key={allocation.id} value={allocation.id}>{allocation.label} · {owner} · {source?.name || "sursa aleasă"} · {money(remaining)} rămași</option>; })}</select></Field>{!envelopeCandidates.length && <small className="bf-envelope-empty">Nu există un plic pentru această combinație de categorie, membru și sursă. Poți înregistra cheltuiala în afara plicurilor sau crea unul în Plan.</small>}</section>}{matchedEnvelope ? <section className={`bf-envelope-match ${envelopeAfter < 0 ? "over" : ""}`}><p>SE VA LUA DIN PLICUL ALES</p><b>{matchedEnvelope.label} · {allocationMember} · {data.settings.paymentSources.find((source) => source.id === matchedEnvelope.sourceId)?.name || "sursa aleasă"}</b><span>{money(Math.max(0, envelopeRemaining))} rămași din limita ajustată de {money(allocationBudget(data, matchedEnvelope))}{proposedAmount > 0 ? envelopeAfter < 0 ? ` · depășești plicul cu ${money(Math.abs(envelopeAfter))}` : ` · după plată rămân ${money(envelopeAfter)}` : ""}</span>{matchedEnvelope.note && <small>{matchedEnvelope.note}</small>}</section> : kind === "expense" && <section className="bf-envelope-match outside"><p>PLATĂ ÎN AFARA PLICURILOR</p><b>Va scădea doar soldul sursei reale de plată.</b><span>Nu consumă nicio limită repartizată pentru categorii.</span></section>}<Field label="Notiță opțională"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. cursă taxi, traseu, persoană, motiv" /></Field>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={save}><Check size={17} /> Salvează mișcarea</button></Modal>;
}

function GoalForm({ data, type, item, onSave, onClose }: { data: AppData; type: "debt" | "saving"; item?: Debt | SavingsGoal; onSave: (item: Debt | SavingsGoal) => void; onClose: () => void }) {
  const saving = type === "saving"; const old = item as SavingsGoal | undefined; const oldDebt = item as Debt | undefined;
  const [name, setName] = useState(item?.name || ""); const [one, setOne] = useState(item ? String(saving ? old?.current ?? 0 : oldDebt?.remaining ?? 0) : ""); const [two, setTwo] = useState(item ? String(saving ? old?.target ?? 0 : oldDebt?.monthly ?? 0) : ""); const [date, setDate] = useState(item?.dueDate || ""); const [memberId, setMemberId] = useState(item?.memberId || ""); const [error, setError] = useState("");
  const save = () => { const first = parseRomanianAmount(one); const second = parseRomanianAmount(two); if (!name.trim() || first < 0 || second < 0 || (saving && second <= 0)) return setError("Completează numele și sumele corecte."); if (saving) onSave({ id: item?.id || newId("goal"), name: name.trim(), current: first, target: second, due: date ? dateText(date, true) : "Fără termen", dueDate: date || undefined, memberId: memberId || undefined, tone: old?.tone || "honey" }); else onSave({ id: item?.id || newId("debt"), name: name.trim(), remaining: first, monthly: second, due: date ? dateText(date, true) : "Nespecificat", dueDate: date || undefined, memberId: memberId || undefined, tone: oldDebt?.tone || "coral" }); onClose(); };
  return <Modal title={saving ? "Obiectiv de economisire" : "Datorie sau rată"} onClose={onClose}><div className="bf-form-grid"><Field label={saving ? "Pentru ce economisiți?" : "Denumire"}><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder={saving ? "ex. Fond de siguranță" : "ex. Credit bancar"} /></Field><Field label="Aparține de"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}><option value="">Familie / comun</option>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label={saving ? "Strâns până acum (lei)" : "Sold rămas (lei)"}><input value={one} onChange={(event) => setOne(event.target.value)} inputMode="decimal" /></Field><Field label={saving ? "Țintă (lei)" : "Rată lunară (lei)"}><input value={two} onChange={(event) => setTwo(event.target.value)} inputMode="decimal" /></Field><Field label={saving ? "Data țintă" : "Scadență"}><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field></div>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={save}><Check size={17} /> Salvează</button></Modal>;
}

function DebtPaymentForm({ data, debt, onSave, onClose }: { data: AppData; debt: Debt; onSave: (data: AppData) => void; onClose: () => void }) {
  const [amount, setAmount] = useState(String(Math.min(debt.monthly || debt.remaining, debt.remaining))); const [date, setDate] = useState(isoToday()); const [memberId, setMemberId] = useState(debt.memberId || data.settings.members[0]?.id || ""); const paymentSources = data.settings.paymentSources.filter((source) => !source.memberId || source.memberId === memberId); const [sourceId, setSourceId] = useState(data.settings.paymentSources.find((source) => source.memberId === debt.memberId)?.id || data.settings.paymentSources[0]?.id || ""); const [note, setNote] = useState(""); const [error, setError] = useState("");
  const pay = () => { const value = parseRomanianAmount(amount); if (value <= 0) return setError("Introdu o sumă mai mare decât zero."); if (value > debt.remaining) return setError(`Poți plăti cel mult ${money(debt.remaining)} pentru această datorie.`); const next = recordDebtPayment(data, { debtId: debt.id, amount: value, sourceId, memberId, date, note }); if (!next) return setError("Alege un membru și o sursă de plată valide."); if (!window.confirm(`Confirmi plata de ${money(value)} pentru „${debt.name}”? Soldul datoriei va deveni ${money(debt.remaining - value)}.`)) return; onSave(next); onClose(); };
  const ownerName = (sourceId: string) => data.settings.members.find((member) => member.id === data.settings.paymentSources.find((source) => source.id === sourceId)?.memberId)?.name || "Comun";
  return <Modal title={`Plătește rata · ${debt.name}`} onClose={onClose}><section className="bf-debt-payment-intro"><p className="bf-kicker">MIȘCARE REALĂ + DATORIE</p><p>Plata este adăugată în Jurnal și scade aceeași sumă din soldul rămas. Nu pornește plăți bancare automate.</p><strong>{money(debt.remaining)} rămași</strong></section><div className="bf-form-grid"><Field label="Sumă plătită (lei)"><input autoFocus value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" /></Field><Field label="Data plății"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Membru"><select value={memberId} onChange={(event) => { const nextMember = event.target.value; setMemberId(nextMember); const firstSource = data.settings.paymentSources.find((source) => !source.memberId || source.memberId === nextMember); if (firstSource) setSourceId(firstSource.id); }}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label="Plătit din"><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {ownerName(source.id)} · {money(sourceBalance(data, source.id))}</option>)}</select></Field></div><Field label="Notiță opțională"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. rata august, plată parțială" /></Field>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={pay}><Check size={17} /> Confirmă plata ratei</button></Modal>;
}

function BudgetBar({ used, total, tone = "green" }: { used: number; total: number; tone?: "green" | "gold" | "coral" }) { const percent = total > 0 ? Math.min(100, Math.max(0, used / total * 100)) : 0; return <div className={`bf-progress ${tone}`} aria-label={`${Math.round(percent)}% utilizat`}><span style={{ width: `${percent}%` }} /></div>; }

function BalancePanel({ data, start, end, onReports }: { data: AppData; start?: string; end?: string; onReports: () => void }) {
  const isCollaborative = data.settings.members.length > 1; const [scope, setScope] = useState("family"); const selectedMember = data.settings.members.find((member) => member.id === scope); const balance = financialBalance(data, start, end, selectedMember?.id); const label = selectedMember ? selectedMember.name : isCollaborative ? "Familie" : "Personal";
  const scopedDebts = data.debts.filter((item) => !selectedMember || !item.memberId || item.memberId === selectedMember.id);
  return <section className="bf-balance-card"><div className="bf-balance-heading"><div><p className="bf-kicker">BILANȚ {label.toUpperCase()}</p><h2>Tragem linie, <em>fără să amestecăm.</em></h2></div><button onClick={onReports}>Rapoarte <ChevronRight size={15} /></button></div>{isCollaborative && <div className="bf-balance-scope" role="group" aria-label="Perspectiva bilanțului"><button className={scope === "family" ? "active" : ""} onClick={() => setScope("family")}>Familie</button>{data.settings.members.map((member) => <button key={member.id} className={scope === member.id ? "active" : ""} onClick={() => setScope(member.id)}>{member.name}</button>)}</div>}<p className="bf-balance-scope-note">{selectedMember ? "Include mișcările și sursele acestui membru, plus obligațiile comune." : "Include toate sursele, mișcările și obligațiile înregistrate."}</p><div className="bf-balance-total"><div><span>Poziție lichidă netă</span><strong className={balance.netLiquidPosition < 0 ? "negative" : ""}>{money(balance.netLiquidPosition)}</strong></div><p>Solduri utilizabile {money(balance.liquidFunds)} − datorii rămase {money(balance.debtRemaining)}</p></div><div className="bf-balance-metrics"><article><span>Fluxul planului</span><b className={balance.cashflow < 0 ? "negative" : ""}>{money(balance.cashflow)}</b><small>venituri {money(balance.income)} − cheltuieli {money(balance.expense)}</small></article><article><span>Rate declarate / lună</span><b>{money(balance.monthlyRates)}</b><small>{scopedDebts.length} obligații personale sau comune</small></article><article><span>Economii urmărite</span><b>{money(balance.savingsCurrent)}</b><small>afișate separat pentru a evita dublarea soldurilor</small></article></div></section>;
}

function planMath(data: AppData) {
  const plan = data.settings.salaryPlan;
  const planEnd = planEndDate(plan);
  const sourceIds = plan.sourceIds.length ? plan.sourceIds : data.settings.paymentSources.map((source) => source.id);
  const selected = data.settings.paymentSources.filter((source) => sourceIds.includes(source.id));
  const availableSources = selected.reduce((sum, source) => sum + sourceBalance(data, source.id), 0);
  const periodExpenses = data.transactions.filter((item) => item.kind === "expense" && inPlanPeriod(item.date, plan)).reduce((sum, item) => sum + item.amount, 0);
  const budget = plan.totalLimit || Math.max(0, availableSources);
  const days = planEnd ? Math.max(1, Math.floor((new Date(`${planEnd}T12:00:00`).valueOf() - new Date(`${plan.periodStart}T12:00:00`).valueOf()) / 86400000) + 1) : 7;
  const weeks = Math.max(1, Math.ceil(days / 7));
  const weekly = plan.weeklyLimit || budget / weeks;
  const scheduled = pendingRecurringInPlan(data).reduce((sum, item) => sum + item.amount, 0);
  return { plan, planEnd, sourceIds, selected, availableSources, budget, periodExpenses, scheduled, remaining: budget - periodExpenses - scheduled, days, weeks, weekly };
}

function advisorSignals(data: AppData): AdvisorSignal[] {
  const math = planMath(data);
  const forecast = planForecast(data);
  const signals: AdvisorSignal[] = [];
  const pending = pendingRecurringInPlan(data).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  if (!math.plan.nextPayday) {
    signals.push({ id: "plan-needed", tone: "watch", eyebrow: "URMĂTORUL PAS", title: "Alege următorul venit", detail: "Planul are nevoie de o dată de salariu pentru a calcula ritmul sigur de cheltuire.", action: "plan", actionLabel: "Configurează planul" });
  } else if (math.remaining < 0) {
    signals.push({ id: "over-plan", tone: "risk", eyebrow: "ATENȚIE", title: `Planul este peste limită cu ${money(Math.abs(math.remaining))}`, detail: `Sunt incluse ${money(math.periodExpenses)} cheltuieli și ${money(math.scheduled)} rezervate până la ${dateText(math.planEnd || math.plan.nextPayday)}.`, action: "plan", actionLabel: "Revizuiește planul" });
  } else if (forecast.spentToDate > 0 && forecast.projectedRemaining < 0) {
    signals.push({ id: "pace-risk", tone: "risk", eyebrow: "RITM DE REVIZUIT", title: `La ritmul actual lipsesc ${money(Math.abs(forecast.projectedRemaining))}`, detail: `Cheltuielile sunt în medie ${money(forecast.paceDaily)} pe zi; ritmul sigur este ${money(forecast.safeDaily)} pe zi până la venit.`, action: "plan", actionLabel: "Ajustează planul" });
  } else {
    const daily = math.remaining / Math.max(1, math.days);
    signals.push({ id: "daily-pace", tone: "good", eyebrow: "RITM SIGUR", title: `${money(daily)} pe zi până la venit`, detail: `${money(math.remaining)} rămân după cheltuielile înregistrate și rezervele deja planificate.`, action: "plan", actionLabel: "Vezi calculele" });
  }
  if (pending[0]) {
    signals.push({ id: "next-recurring", tone: "watch", eyebrow: "SCADENȚĂ REZERVATĂ", title: `${pending[0].name} · ${money(pending[0].amount)}`, detail: `Este programată pentru ${dateText(pending[0].dueDate, true)} și este deja exclusă din suma disponibilă.`, action: "recurring", actionLabel: "Deschide scadențele" });
  }
  const allocation = data.settings.salaryPlan.allocations.map((item) => ({ item, ...allocationStatus(data, item) })).sort((a, b) => b.usage - a.usage)[0];
  if (allocation && allocation.state !== "healthy") {
    const over = allocation.state === "over";
    signals.push({ id: `allocation-${allocation.item.id}`, tone: over ? "risk" : "watch", eyebrow: over ? "PLIC DEPĂȘIT" : "APROAPE DE LIMITĂ", title: `${allocation.item.label}: ${money(Math.max(0, allocation.remaining))} rămași`, detail: `${money(allocation.spent)} cheltuiți din limita ajustată de ${money(allocation.budget)} în perioada activă.`, action: "plan", actionLabel: "Vezi plicul" });
  }
  const goal = data.savings.filter((item) => item.target > item.current).sort((a, b) => (b.target - b.current) - (a.target - a.current))[0];
  if (goal && signals.length < 3) signals.push({ id: `goal-${goal.id}`, tone: "good", eyebrow: "OBIECTIV COMUN", title: `${money(goal.target - goal.current)} până la ${goal.name}`, detail: `Progres actual: ${money(goal.current)} din ${money(goal.target)}.`, action: "objectives", actionLabel: "Vezi obiectivul" });
  return signals.slice(0, 3);
}

function HomeView({ data, onAdd, onGo }: { data: AppData; onAdd: () => void; onGo: (view: MainView, more?: MoreView) => void }) {
  const { plan, planEnd, budget, remaining, days, weekly, periodExpenses, scheduled } = planMath(data);
  const forecast = planForecast(data); const isCollaborative = data.settings.members.length > 1;
  const overviewBalance = financialBalance(data, plan.periodStart, planEnd);
  const income = overviewBalance.income;
  const debts = data.debts.reduce((sum, item) => sum + item.monthly, 0);
  const upcoming = data.debts.filter((item) => item.dueDate).sort((a, b) => String(a.dueDate).localeCompare(String(b.dueDate))).slice(0, 2);
  const overPlan = remaining < 0; const measuredSpend = periodExpenses + scheduled; const planProgress = budget > 0 ? Math.min(100, Math.round((measuredSpend / budget) * 100)) : 0; const signals = advisorSignals(data); const priority = signals[0];
  const openSignal = (action: AdvisorAction) => action === "plan" ? onGo("plan") : action === "objectives" ? onGo("objectives") : action === "journal" ? onGo("journal") : onGo("more", "recurring");
  return <div className="bf-page bf-home">
    <header className="bf-topline"><div><p className="bf-kicker">ZIUA DE AZI · {dateText(isoToday(), true)}</p><h1>{isCollaborative ? <>Bună, <em>{data.settings.familyName}.</em></> : <>Astăzi, <em>tu decizi.</em></>}</h1><p>{isCollaborative ? "Ce decizie vă păstrează ritmul până la următorul venit?" : "Ce decizie îți păstrează banii disponibili până la următorul venit?"}</p></div><button className="bf-primary" onClick={onAdd}><Plus size={18} /> Înregistrează</button></header>
    <section className={`bf-safe-card ${overPlan ? "risk" : ""}`}><div><p className="bf-kicker">{overPlan ? "PESTE LIMITA PLANULUI" : "DISPONIBIL ÎN PLAN"}</p><strong>{money(remaining)}</strong><p>{overPlan ? `Planul este depășit cu ${money(Math.abs(remaining))}. Verifică sursele sau limita.` : plan.nextPayday ? `${days} zile până la următorul venit${plan.earliestPayday ? ` · calcul prudent până la ${dateText(planEnd || plan.nextPayday)}` : ""} · limită recomandată ${money(weekly)}/săptămână` : "Alege următorul venit în Plan"}</p></div><div className="bf-safe-stats"><span><b>{money(budget)}</b> planificat</span><span><b>{money(periodExpenses)}</b> cheltuit</span>{scheduled > 0 && <span><b>{money(scheduled)}</b> de rezervat</span>}<button onClick={() => onGo("plan")}>Revizuiește planul <ChevronRight size={15} /></button></div><div className="bf-plan-measure"><div role="progressbar" aria-label="Plan consumat" aria-valuemin={0} aria-valuemax={100} aria-valuenow={planProgress}><i style={{ width: `${planProgress}%` }} /></div><p><span>0</span><b>{budget > 0 ? `${planProgress}% din plan angajat` : "configurează limita"}</b><span>{budget > 0 ? money(budget) : ""}</span></p></div></section>
    <section className="bf-decision-rail" aria-label="Ritm și următoarea decizie"><div><p>RITM SIGUR</p><strong>{plan.nextPayday ? money(forecast.safeDaily) : "—"}<small>{plan.nextPayday && "/zi"}</small></strong><span>{plan.nextPayday ? "fără să depășești planul" : "alege întâi data venitului"}</span></div><div><p>ORIZONT</p><strong>{plan.nextPayday ? days : "—"}<small>{plan.nextPayday && " zile"}</small></strong><span>{plan.nextPayday ? "până la următorul venit" : "planul este deschis"}</span></div><button onClick={() => priority ? openSignal(priority.action) : onGo("plan")}><span>URMĂTORUL PAS</span><b>{priority?.actionLabel || "Configurează planul"}</b><ChevronRight size={17} /></button></section>
    <section className="bf-family-checkin" aria-labelledby="checkin-title"><div className="bf-checkin-heading"><div><p className="bf-kicker">PUNCT DE DECIZIE</p><h2 id="checkin-title">Ce merită decis acum</h2></div><button onClick={() => onGo("more", "assistant")}><Bot size={16} /> Asistent</button></div><div className="bf-checkin-list">{signals.map((signal) => <article key={signal.id} className={signal.tone}><span className="bf-checkin-dot" aria-hidden="true" /><div><p>{signal.eyebrow}</p><b>{signal.title}</b><small>{signal.detail}</small></div><button onClick={() => openSignal(signal.action)}>{signal.actionLabel}<ChevronRight size={15} /></button></article>)}</div></section>
    <div className="bf-quick-grid"><button onClick={onAdd}><WalletCards size={19} /><span>Înregistrează</span><small>o mișcare</small></button><button onClick={() => onGo("plan")}><CalendarDays size={19} /><span>Planifică</span><small>până la venit</small></button><button onClick={() => onGo("more", "assistant")}><Bot size={19} /><span>Simulează</span><small>o decizie</small></button></div>
    <section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">PULSUL PERIOADEI</p><h2>Unde este atenția acum</h2></div><button onClick={() => onGo("journal")}>Jurnal <ChevronRight size={15} /></button></div><div className="bf-pulse-grid"><article><span className="bf-pulse-icon income"><ArrowDownRight size={16} /></span><p>Venituri</p><strong>{money(income)}</strong></article><article><span className="bf-pulse-icon debt"><BellRing size={16} /></span><p>Rate lunare</p><strong>{money(debts)}</strong></article><article><span className="bf-pulse-icon goal"><PiggyBank size={16} /></span><p>Economii</p><strong>{money(data.savings.reduce((sum, item) => sum + item.current, 0))}</strong></article></div></section>
    <BalancePanel data={data} start={plan.periodStart} end={planEnd} onReports={() => onGo("more", "reports")} />
    {upcoming.length > 0 && <section className="bf-upcoming"><p className="bf-kicker">URMĂTOARELE OBLIGAȚII</p>{upcoming.map((debt) => <div key={debt.id}><span>{debt.name}<small>{debt.due}</small></span><b>{money(debt.monthly)}</b></div>)}</section>}
    <section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">ULTIMELE MIȘCĂRI</p><h2>{isCollaborative ? "Registrul comun" : "Registrul personal"}</h2></div><button onClick={() => onGo("journal")}>Vezi toate <ChevronRight size={15} /></button></div><div className="bf-ledger-mini">{data.transactions.slice(0, 5).map((item) => <div key={item.id}><span className={`bf-tx-icon ${item.kind}`} >{item.kind === "income" ? <ArrowDownRight size={16} /> : <ArrowUpRight size={16} />}</span><span><b>{item.title}</b><small>{dateText(item.date)} · {item.person} · {item.source}</small></span><strong className={item.kind}>{item.kind === "income" ? "+" : "−"}{fmtExact.format(item.amount)}</strong></div>)}{!data.transactions.length && <p className="bf-empty-inline"><b>Prima decizie:</b> înregistrează prima mișcare, apoi planul va arăta ce poate fi cheltuit liniștit.</p>}</div></section>
  </div>;
}

function JournalView({ data, onEdit, onDelete, onAdd }: { data: AppData; onEdit: (item: Transaction) => void; onDelete: (id: string) => void; onAdd: () => void }) {
  const [kind, setKind] = useState<"all" | TransactionKind>("all"); const [member, setMember] = useState("all"); const [source, setSource] = useState("all");
  const list = data.transactions.filter((item) => (kind === "all" || item.kind === kind) && (member === "all" || item.memberId === member) && (source === "all" || item.sourceId === source));
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">JURNAL DE FAMILIE</p><h1>Fiecare leu, <em>cu context.</em></h1></div><button className="bf-primary" onClick={onAdd}><Plus size={18} /> Adaugă</button></header><section className="bf-filter-sheet"><div className="bf-segment small"><button className={kind === "all" ? "active" : ""} onClick={() => setKind("all")}>Toate</button><button className={kind === "expense" ? "active expense" : ""} onClick={() => setKind("expense")}>Cheltuieli</button><button className={kind === "income" ? "active income" : ""} onClick={() => setKind("income")}>Venituri</button></div><div className="bf-filter-selects"><select value={member} onChange={(event) => setMember(event.target.value)}><option value="all">Toți membrii</option>{data.settings.members.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={source} onChange={(event) => setSource(event.target.value)}><option value="all">Toate sursele</option>{data.settings.paymentSources.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div></section><section className="bf-journal">{list.map((item) => <article key={item.id}><span className={`bf-tx-icon ${item.kind}`}>{item.kind === "income" ? <ArrowDownRight size={17} /> : <ArrowUpRight size={17} />}</span><div className="bf-journal-name"><b>{item.title}</b><small>{dateText(item.date, true)} · {item.person} · {item.source}</small><span>{item.category}{item.note ? ` · ${item.note}` : ""}</span></div><strong className={item.kind}>{item.kind === "income" ? "+" : "−"}{fmtExact.format(item.amount)}</strong><div className="bf-row-actions"><button aria-label={`Modifică ${item.title}`} onClick={() => onEdit(item)}>Modifică</button><button aria-label={`Șterge ${item.title}`} onClick={() => window.confirm(`Ștergi mișcarea „${item.title}”?`) && onDelete(item.id)}><Trash2 size={16} /></button></div></article>)}{!list.length && <div className="bf-empty-state"><ReceiptText size={24} /><h2>Nu sunt mișcări în acest filtru</h2><p>Schimbă filtrul sau adaugă prima intrare.</p><button className="bf-primary" onClick={onAdd}><Plus size={16} /> Adaugă mișcare</button></div>}</section></div>;
}

function EnvelopeInsights({ data }: { data: AppData }) {
  const plan = data.settings.salaryPlan; const planEnd = planEndDate(plan); const envelopes = plan.allocations.filter((item) => Boolean(item.category)); const [selectedId, setSelectedId] = useState(envelopes[0]?.id || ""); const [transferEnvelope, setTransferEnvelope] = useState("all"); const [transferSource, setTransferSource] = useState("all"); const [transferRange, setTransferRange] = useState<"all" | "7" | "period">("period");
  const rows = envelopes.map((item) => ({ item, ...allocationStatus(data, item), source: data.settings.paymentSources.find((source) => source.id === item.sourceId) })); const selected = rows.find((row) => row.item.id === selectedId) || rows[0]; const alerts = rows.filter((row) => row.state !== "healthy");
  const transfers = plan.transfers.filter((transfer) => { const from = plan.allocations.find((item) => item.id === transfer.fromAllocationId); const to = plan.allocations.find((item) => item.id === transfer.toAllocationId); const timestamp = transfer.createdAt.slice(0, 10); const matchesEnvelope = transferEnvelope === "all" || transfer.fromAllocationId === transferEnvelope || transfer.toAllocationId === transferEnvelope; const matchesSource = transferSource === "all" || from?.sourceId === transferSource || to?.sourceId === transferSource; const matchesRange = transferRange === "all" || (transferRange === "period" ? timestamp >= plan.periodStart && (!planEnd || timestamp <= planEnd) : Date.now() - new Date(transfer.createdAt).valueOf() <= 7 * 86400000); return matchesEnvelope && matchesSource && matchesRange; }).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  if (!rows.length) return null;
  return <><section className="bf-envelope-insights"><div className="bf-section-heading"><div><p className="bf-kicker">4. PULSUL PLICURILOR</p><h2>Alocat, cheltuit, rămas</h2></div><span>{rows.length} categorii</span></div><p className="bf-envelope-intro">Atinge o categorie pentru detaliu. Barele arată cheltuitul din limita ajustată prin realocări.</p>{alerts.length > 0 && <div className="bf-envelope-alerts" role="status">{alerts.map((row) => <button key={row.item.id} className={row.state} onClick={() => setSelectedId(row.item.id)}>{row.state === "over" ? "Plic depășit" : "Aproape de limită"}<b>{row.item.label}</b><span>{row.state === "over" ? `${money(Math.abs(row.remaining))} peste limită` : `${Math.round(row.usage * 100)}% utilizat`}</span></button>)}</div>}<div className="bf-envelope-chart" role="list" aria-label="Plicuri de categorie">{rows.map((row) => { const color = categoryColors[row.item.category || ""] || "#4f8a74"; return <button key={row.item.id} role="listitem" className={`${row.state} ${selected?.item.id === row.item.id ? "selected" : ""}`} aria-pressed={selected?.item.id === row.item.id} onClick={() => setSelectedId(row.item.id)}><span className="bf-envelope-chart-name"><i style={{ backgroundColor: color }} /><b>{row.item.label}</b><small>{money(row.spent)} / {money(row.budget)}</small></span><span className="bf-envelope-track"><i style={{ width: `${Math.min(100, Math.max(0, row.usage * 100))}%`, backgroundColor: row.state === "over" ? "#d56852" : row.state === "watch" ? "#d49a2a" : color }} /></span><strong>{money(Math.max(0, row.remaining))}</strong></button>; })}</div>{selected && <article className={`bf-envelope-detail ${selected.state}`}><div><p>{selected.state === "over" ? "NECESITĂ REALOCARE" : selected.state === "watch" ? "PRAG DE ATENȚIE" : "ÎN LIMITE"}</p><h3>{selected.item.label}</h3><span>{selected.source?.name || "Orice sursă"}{selected.item.note ? ` · ${selected.item.note}` : ""}</span></div><div><b>{money(Math.max(0, selected.remaining))}</b><small>rămași din {money(selected.budget)}</small></div></article>}</section><section className="bf-transfer-log"><div className="bf-section-heading"><div><p className="bf-kicker">ISTORIC REALOCĂRI</p><h2>Unde au fost mutate limitele</h2></div><span>{transfers.length} afișate</span></div><div className="bf-transfer-filters"><select value={transferEnvelope} onChange={(event) => setTransferEnvelope(event.target.value)}><option value="all">Toate plicurile</option>{envelopes.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select><select value={transferSource} onChange={(event) => setTransferSource(event.target.value)}><option value="all">Toate sursele</option>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name}</option>)}</select><select value={transferRange} onChange={(event) => setTransferRange(event.target.value as typeof transferRange)}><option value="period">Perioada planului</option><option value="7">Ultimele 7 zile</option><option value="all">Tot istoricul</option></select></div><div className="bf-transfer-log-list">{transfers.map((transfer) => { const from = plan.allocations.find((item) => item.id === transfer.fromAllocationId); const to = plan.allocations.find((item) => item.id === transfer.toAllocationId); return <article key={transfer.id}><span><ArrowLeftRight size={16} /></span><div><b>{from?.label || "Plic șters"} → {to?.label || "Plic șters"}</b><small>{dateText(transfer.createdAt.slice(0, 10), true)}{transfer.note ? ` · ${transfer.note}` : ""}</small></div><strong>{money(transfer.amount)}</strong></article>; })}{!transfers.length && <p className="bf-empty-inline">Nu există realocări pentru aceste filtre.</p>}</div></section></>;
}

function EnvelopeTransferPanel({ data, onChange }: { data: AppData; onChange: (data: AppData) => void }) {
  const plan = data.settings.salaryPlan; const envelopes = plan.allocations.filter((item) => Boolean(item.category)); const [fromId, setFromId] = useState(envelopes[0]?.id || ""); const [toId, setToId] = useState(""); const [amount, setAmount] = useState(""); const [note, setNote] = useState(""); const [error, setError] = useState("");
  const from = envelopes.find((item) => item.id === fromId) || envelopes[0]; const compatible = envelopes.filter((item) => item.id !== from?.id && item.sourceId === from?.sourceId); const to = compatible.find((item) => item.id === toId) || compatible[0]; const available = from ? Math.max(0, allocationBudget(data, from) - allocationSpent(data, from)) : 0;
  const transfer = () => { const numeric = parseRomanianAmount(amount); if (!from || !to) return setError("Alege două plicuri de categorii finanțate din aceeași sursă."); if (from.id === to.id) return setError("Alege un plic destinație diferit."); if (numeric <= 0) return setError("Introdu o sumă mai mare decât zero."); if (numeric > available) return setError(`Poți muta cel mult ${money(available)} din ${from.label}.`); onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, transfers: [...plan.transfers, { id: newId("allocation-transfer"), fromAllocationId: from.id, toAllocationId: to.id, amount: numeric, note: note.trim() || undefined, createdAt: new Date().toISOString() }], updatedAt: new Date().toISOString() } } }); setAmount(""); setNote(""); setError(""); };
  if (envelopes.length < 2) return <><EnvelopeInsights data={data} /><section className="bf-transfer-panel empty"><div><p className="bf-kicker">5. REALOCARE</p><h2>Mută între plicuri</h2><span>Adaugă minimum două plicuri de categorii pentru a putea muta bugetul între ele.</span></div></section></>;
  return <><EnvelopeInsights data={data} /><section className="bf-transfer-panel"><div className="bf-section-heading"><div><p className="bf-kicker">5. REALOCARE</p><h2>Mută bani între plicuri</h2></div><ArrowLeftRight size={19} /></div><p>Nu este o plată și nu modifică soldul cardului sau cash-ului. Mută doar limita dintre două plicuri cu aceeași sursă.</p><div className="bf-transfer-form"><Field label="Din plic"><select value={from?.id || ""} onChange={(event) => { setFromId(event.target.value); setToId(""); }}>{envelopes.map((item) => <option key={item.id} value={item.id}>{item.label} · {money(Math.max(0, allocationBudget(data, item) - allocationSpent(data, item)))}</option>)}</select></Field><Field label="Către plic"><select value={to?.id || ""} onChange={(event) => setToId(event.target.value)} disabled={!compatible.length}>{compatible.map((item) => <option key={item.id} value={item.id}>{item.label} · {money(Math.max(0, allocationBudget(data, item) - allocationSpent(data, item)))}</option>)}</select></Field><Field label="Sumă de mutat"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder={money(available)} /></Field><Field label="Explicație opțională"><input value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. Taxi depășit, mut din timp liber" /></Field><button className="bf-secondary" disabled={!to} onClick={transfer}><ArrowLeftRight size={17} /> Mută bugetul</button></div>{error && <p className="bf-form-error" role="alert">{error}</p>}</section></>;
}

function LegacyPlanView({ data, onChange }: { data: AppData; onChange: (data: AppData) => void }) {
  const plan = data.settings.salaryPlan; const [allocationMode, setAllocationMode] = useState<"member" | "category">("member"); const [target, setTarget] = useState(data.settings.members[0]?.id || ""); const [amount, setAmount] = useState(""); const [allocationSourceId, setAllocationSourceId] = useState(data.settings.paymentSources[0]?.id || ""); const [allocationNote, setAllocationNote] = useState("");
  const maths = planMath(data); const updatePlan = (patch: Partial<typeof plan>) => onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, ...patch } } });
  const toggleSource = (id: string) => { const all = data.settings.paymentSources.map((item) => item.id); const current = plan.sourceIds.length ? plan.sourceIds : all; const next = current.includes(id) ? current.filter((value) => value !== id) : [...current, id]; updatePlan({ sourceIds: next.length === all.length ? [] : next }); };
  const addAllocation = () => { const numeric = parseRomanianAmount(amount); const source = data.settings.paymentSources.find((item) => item.id === allocationSourceId); if (numeric <= 0 || !source) return; const member = data.settings.members.find((item) => item.id === target); const allocation: BudgetAllocation = { id: newId("allocation"), label: allocationMode === "member" ? member?.name || "Membru" : target, amount: numeric, memberId: allocationMode === "member" ? target : undefined, category: allocationMode === "category" ? target : undefined, sourceId: source.id, note: allocationNote.trim() || undefined }; updatePlan({ allocations: [...plan.allocations, allocation] }); setAmount(""); setAllocationNote(""); };
  const periods = Array.from({ length: maths.weeks }, (_, index) => { const start = new Date(`${plan.periodStart}T12:00:00`); start.setDate(start.getDate() + index * 7); const end = new Date(Math.min(start.valueOf() + 6 * 86400000, plan.nextPayday ? new Date(`${plan.nextPayday}T12:00:00`).valueOf() : start.valueOf() + 6 * 86400000)); const startIso = start.toISOString().slice(0, 10); const endIso = end.toISOString().slice(0, 10); const spent = data.transactions.filter((item) => item.kind === "expense" && item.date >= startIso && item.date <= endIso).reduce((sum, item) => sum + item.amount, 0); const allowance = index === maths.weeks - 1 ? Math.max(0, maths.budget - maths.weekly * index) : maths.weekly; return { start, end, spent, allowance }; });
  const targets = allocationMode === "member" ? data.settings.members.map((item) => ({ id: item.id, name: item.name })) : [...expenseCategories, ...data.settings.customCategories].map((item) => ({ id: item, name: item }));
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">PLAN PÂNĂ LA URMĂTORUL VENIT</p><h1>Fă loc banilor <em>înainte de cheltuială.</em></h1></div></header><section className="bf-plan-hero"><div><p>Disponibil în această perioadă</p><strong>{money(Math.max(0, maths.remaining))}</strong><span>{maths.days} zile · {maths.weeks} săptămâni · {money(maths.weekly)} / săptămână</span></div><div className="bf-plan-hero-data"><span>Buget <b>{money(maths.budget)}</b></span><span>Cheltuit <b>{money(maths.periodExpenses)}</b></span><span>Surse <b>{money(maths.availableSources)}</b></span></div></section><section className="bf-period-card"><div className="bf-section-heading"><div><p className="bf-kicker">1. PERIOADA</p><h2>Când intră următorii bani?</h2></div><CalendarDays size={19} /></div><div className="bf-form-grid"><Field label="Începe la"><input type="date" value={plan.periodStart} onChange={(event) => updatePlan({ periodStart: event.target.value })} /></Field><Field label="Următorul salariu / venit"><input type="date" min={plan.periodStart} value={plan.nextPayday} onChange={(event) => updatePlan({ nextPayday: event.target.value })} /></Field></div></section><section className="bf-period-card"><div className="bf-section-heading"><div><p className="bf-kicker">2. BANII DE FOLOSIT</p><h2>Alege sursele și limita</h2></div><WalletCards size={19} /></div><div className="bf-source-list">{data.settings.paymentSources.map((source) => { const active = !plan.sourceIds.length || plan.sourceIds.includes(source.id); return <label key={source.id} className={active ? "active" : ""}><input type="checkbox" checked={active} onChange={() => toggleSource(source.id)} /><span><b>{source.name}</b><small>{data.settings.members.find((member) => member.id === source.memberId)?.name || "Comun"}</small></span><strong>{money(sourceBalance(data, source.id))}</strong></label>; })}</div><div className="bf-form-grid"><Field label="Limită totală pentru perioadă" hint="Dacă rămâne goală, se folosește soldul surselor selectate."><input inputMode="decimal" value={plan.totalLimit ? String(plan.totalLimit) : ""} onChange={(event) => updatePlan({ totalLimit: Math.max(0, parseRomanianAmount(event.target.value)) })} placeholder={maths.availableSources ? money(maths.availableSources) : "ex. 600"} /></Field><Field label="Limită săptămânală" hint="Dacă rămâne goală, împărțim automat."><input inputMode="decimal" value={plan.weeklyLimit ? String(plan.weeklyLimit) : ""} onChange={(event) => updatePlan({ weeklyLimit: Math.max(0, parseRomanianAmount(event.target.value)) })} placeholder={money(maths.budget / maths.weeks)} /></Field></div></section><section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">3. RITMUL SĂPTĂMÂNII</p><h2>Bugetat, cheltuit, rămas</h2></div></div><div className="bf-week-list">{periods.map((week, index) => <article key={index}><div><b>Săpt. {index + 1}</b><small>{dateText(week.start.toISOString().slice(0, 10))} – {dateText(week.end.toISOString().slice(0, 10))}</small></div><strong>{money(Math.max(0, week.allowance - week.spent))}</strong><BudgetBar used={week.spent} total={week.allowance} tone={week.spent > week.allowance ? "coral" : "gold"} /><span>{money(week.spent)} cheltuit din {money(week.allowance)}</span></article>)}</div></section><section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">4. PLICURI DE BUGET</p><h2>Repartizează pentru oameni și categorii</h2></div></div><div className="bf-allocation-form"><select value={allocationMode} onChange={(event) => { const mode = event.target.value as typeof allocationMode; setAllocationMode(mode); setTarget(mode === "member" ? data.settings.members[0]?.id || "" : expenseCategories[0]); }}><option value="member">Membru</option><option value="category">Categorie</option></select><select value={target} onChange={(event) => setTarget(event.target.value)}>{targets.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><select value={allocationSourceId} onChange={(event) => setAllocationSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {money(sourceBalance(data, source.id))}</option>)}</select><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="lei" /><input value={allocationNote} onChange={(event) => setAllocationNote(event.target.value)} placeholder="Detaliu opțional, ex. Taxi până la venit" /><button className="bf-primary" onClick={addAllocation}><Plus size={17} /> Alocă</button></div><p className="bf-allocation-helper">Alege sursa care finanțează plicul. Orice cheltuială cu aceeași categorie și sursă îl consumă automat.</p><div className="bf-allocation-list">{plan.allocations.map((allocation) => { const spent = allocationSpent(data, allocation); const sourceName = data.settings.paymentSources.find((source) => source.id === allocation.sourceId)?.name; return <article key={allocation.id}><div><b>{allocation.label}</b><small>{allocation.memberId ? "Buget personal" : "Plic de categorie"}{sourceName ? ` · ${sourceName}` : " · orice sursă"}{allocation.note ? ` · ${allocation.note}` : ""}</small></div><div><strong>{money(Math.max(0, allocation.amount - spent))}</strong><span>rămas din {money(allocation.amount)}</span></div><BudgetBar used={spent} total={allocation.amount} tone={spent > allocation.amount ? "coral" : "green"} /><button aria-label={`Șterge ${allocation.label}`} onClick={() => updatePlan({ allocations: plan.allocations.filter((item) => item.id !== allocation.id) })}><Trash2 size={16} /></button></article>; })}{!plan.allocations.length && <p className="bf-empty-inline">Alocă, de exemplu, 300 lei pentru fiecare membru sau 150 lei pentru Taxi.</p>}</div></section></div>;
}

function ObjectivesView({ data, onEditDebt, onEditSaving, onPayDebt, onDeleteDebt, onDeleteSaving, openDebt, openSaving }: { data: AppData; onEditDebt: (item: Debt) => void; onEditSaving: (item: SavingsGoal) => void; onPayDebt: (item: Debt) => void; onDeleteDebt: (id: string) => void; onDeleteSaving: (id: string) => void; openDebt: () => void; openSaving: () => void }) { return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">OBLIGAȚII ȘI OBIECTIVE</p><h1>Ce protejăm și <em>ce construim.</em></h1></div></header><section className="bf-objective-switch"><button className="bf-primary" onClick={openDebt}><Plus size={17} /> Datorie</button><button className="bf-secondary" onClick={openSaving}><Plus size={17} /> Economie</button></section><div className="bf-objective-columns"><section><div className="bf-section-heading"><div><p className="bf-kicker">DATORII</p><h2>Rate și împrumuturi</h2></div><span>{money(data.debts.reduce((sum, item) => sum + item.remaining, 0))}</span></div>{data.debts.map((debt) => <article className="bf-objective-card debt" key={debt.id}><div><b>{debt.name}</b><small>{debt.due}</small></div><strong>{money(debt.remaining)}</strong><p>Rată: {money(debt.monthly)} / lună</p><div className="bf-objective-actions"><button className="bf-objective-pay" aria-label={`Plătește rata ${debt.name}`} onClick={() => onPayDebt(debt)}><Check size={16} /><span>Plătește rata</span></button><button className="bf-objective-edit" aria-label={`Editează ${debt.name}`} onClick={() => onEditDebt(debt)}><Pencil size={16} /><span>Editează</span></button><button aria-label={`Șterge ${debt.name}`} onClick={() => onDeleteDebt(debt.id)}><Trash2 size={16} /></button></div></article>)}{!data.debts.length && <div className="bf-empty-state slim"><BellRing size={23} /><h2>Nicio datorie</h2><p>Adaugă ratele pe care vrei să le incluzi în plan.</p></div>}</section><section><div className="bf-section-heading"><div><p className="bf-kicker">ECONOMII</p><h2>Ținte comune</h2></div><span>{money(data.savings.reduce((sum, item) => sum + item.current, 0))}</span></div>{data.savings.map((saving) => <article className="bf-objective-card saving" key={saving.id}><div><b>{saving.name}</b><small>{saving.due}</small></div><strong>{money(saving.current)}</strong><BudgetBar used={saving.current} total={saving.target} tone="gold" /><p>{money(Math.max(0, saving.target - saving.current))} până la {money(saving.target)}</p><div className="bf-objective-actions"><button className="bf-objective-edit" aria-label={`Editează ${saving.name}`} onClick={() => onEditSaving(saving)}><Pencil size={16} /><span>Editează</span></button><button aria-label={`Șterge ${saving.name}`} onClick={() => onDeleteSaving(saving.id)}><Trash2 size={16} /></button></div></article>)}{!data.savings.length && <div className="bf-empty-state slim"><PiggyBank size={23} /><h2>Niciun obiectiv</h2><p>Începe cu un fond de siguranță sau o țintă importantă.</p></div>}</section></div></div>; }

function ReceiptForm({ data, onSave, onClose }: { data: AppData; onSave: (item: Receipt) => void; onClose: () => void }) {
  const [vendor, setVendor] = useState(""); const [amount, setAmount] = useState(""); const [date, setDate] = useState(isoToday()); const [sourceId, setSourceId] = useState(data.settings.paymentSources[0]?.id || ""); const [memberId, setMemberId] = useState(data.settings.members[0]?.id || ""); const [note, setNote] = useState(""); const [images, setImages] = useState<string[]>([]); const [lines, setLines] = useState<Array<{ id: string; category: string; amount: string; label: string }>>([{ id: newId("receipt-line"), category: "Alimente", amount: "", label: "" }]); const [ocrText, setOcrText] = useState(""); const [ocrSummary, setOcrSummary] = useState(""); const [busy, setBusy] = useState(false); const [progress, setProgress] = useState(0); const [error, setError] = useState("");
  const categories = [...expenseCategories, ...data.settings.customCategories];
  const lineTotal = lines.reduce((sum, line) => sum + parseRomanianAmount(line.amount), 0);
  const pick = async (files?: FileList | null) => {
    const selected = files ? Array.from(files) : [];
    if (!selected.length) return;
    if (images.length + selected.length > 2) return setError("Un bon poate avea maximum două fotografii. Elimină una înainte de a adăuga alta.");
    try { setBusy(true); setError(""); const { compressReceiptImage } = await import("@/lib/receipt-utils"); const compressed = await Promise.all(selected.map(compressReceiptImage)); setImages((current) => [...current, ...compressed]); } catch (reason) { setError(reason instanceof Error ? reason.message : "Poza bonului nu a putut fi procesată."); } finally { setBusy(false); }
  };
  const scan = async () => {
    try { setBusy(true); setError(""); setOcrSummary(""); setProgress(0); const { readReceiptLocally } = await import("@/lib/receipt-utils"); const result = await readReceiptLocally(images, setProgress); setOcrText(result.text); if (result.amount) setAmount(String(result.amount)); if (result.date) setDate(result.date); if (result.text && !note.trim()) setNote(result.text.slice(0, 1400)); if (result.items.length) { const suggestedLines = result.items.map((item) => ({ id: newId("receipt-line"), category: categories.includes(item.category) ? item.category : "Alimente", amount: String(item.amount), label: item.label })); setLines(suggestedLines); const detectedTotal = result.items.reduce((sum, item) => sum + item.amount, 0); setOcrSummary(`Am propus ${result.items.length} produs${result.items.length === 1 ? "" : "e"} cu prețuri individuale (${fmtExact.format(detectedTotal)}). Verifică produsele, categoriile și totalul înainte de salvare.`); } else { setOcrSummary("Am citit textul și totalul, dar nu am identificat sigur linii de produse. Completează repartizarea manual."); } } catch (reason) { setError(reason instanceof Error ? reason.message : "Textul de pe bon nu a putut fi citit."); } finally { setBusy(false); setProgress(0); }
  };
  const updateLine = (id: string, patch: Partial<(typeof lines)[number]>) => setLines((current) => current.map((line) => line.id === id ? { ...line, ...patch } : line));
  const save = () => {
    const numeric = parseRomanianAmount(amount);
    const normalizedLines: ReceiptLine[] = lines.map((line) => ({ id: line.id, category: line.category, amount: parseRomanianAmount(line.amount), label: line.label.trim() || undefined })).filter((line) => line.amount > 0);
    if (normalizedLines.length === 0 && numeric > 0 && lines.length === 1) normalizedLines.push({ id: lines[0].id, category: lines[0].category, amount: numeric, label: lines[0].label.trim() || undefined });
    const splitTotal = normalizedLines.reduce((sum, line) => sum + line.amount, 0);
    if (!vendor.trim() || numeric <= 0 || !sourceId || !memberId) return setError("Completează magazinul, totalul, membrul și sursa.");
    if (!normalizedLines.length || Math.abs(numeric - splitTotal) > 0.01) return setError(`Repartizarea este ${fmtExact.format(splitTotal)}, dar totalul bonului este ${fmtExact.format(numeric)}. Corectează liniile înainte de salvare.`);
    onSave({ id: newId("receipt"), vendor: vendor.trim(), amount: numeric, date, category: normalizedLines[0].category, lines: normalizedLines, sourceId, memberId, note: note.trim() || undefined, imageData: images[0], imageData2: images[1], ocrText: ocrText || undefined }); onClose();
  };
  return <Modal title="Adaugă bon" onClose={onClose}><div className="bf-receipt-intro"><p className="bf-kicker">BON CU REPARTIZARE</p><p>Poți fotografia un bon lung în două părți; imaginile se comprimă local înainte de salvare.</p></div><div className="bf-form-grid"><Field label="Magazin"><input autoFocus value={vendor} onChange={(event) => setVendor(event.target.value)} placeholder="ex. Lidl" /></Field><Field label="Total (lei)"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></Field><Field label="Data"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Membru"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label="Plătit din"><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name}</option>)}</select></Field></div><section className="bf-receipt-images"><div><p className="bf-kicker">FOTOGRAFIILE BONULUI</p><strong>{images.length}/2 imagini</strong></div><label className="bf-upload-control"><Camera size={18} /> {busy && !progress ? "Comprimăm…" : "Adaugă poze"}<input type="file" accept="image/*" capture="environment" multiple disabled={busy || images.length >= 2} onChange={(event) => { void pick(event.target.files); event.currentTarget.value = ""; }} /></label>{images.length > 0 && <button className="bf-ocr-button" disabled={busy} onClick={() => void scan()}><Bot size={17} /> {busy && progress ? `Citim ${progress}%` : "Citește produsele și prețurile local"}</button>}<div className="bf-receipt-preview-grid">{images.map((image, index) => <figure key={image}><img src={image} alt={`Previzualizare bon partea ${index + 1}`} /><button aria-label={`Elimină fotografia ${index + 1}`} onClick={() => setImages((current) => current.filter((_, imageIndex) => imageIndex !== index))}><X size={15} /></button></figure>)}</div>{ocrSummary && <p className="bf-ocr-info" role="status"><Bot size={16} /> {ocrSummary}</p>}</section><section className="bf-receipt-split"><div className="bf-split-heading"><div><p className="bf-kicker">PRODUSE ȘI CATEGORII</p><h3>{fmtExact.format(lineTotal)} din {amount ? fmtExact.format(parseRomanianAmount(amount)) : "0,00 RON"}</h3></div><button className="bf-secondary" onClick={() => setLines((current) => [...current, { id: newId("receipt-line"), category: "Alimente", amount: "", label: "" }])}><Plus size={16} /> Produs</button></div>{lines.map((line) => <div className="bf-split-line" key={line.id}><select aria-label="Categorie bon" value={line.category} onChange={(event) => updateLine(line.id, { category: event.target.value })}>{categories.map((item) => <option key={item}>{item}</option>)}</select><input aria-label="Preț produs" value={line.amount} onChange={(event) => updateLine(line.id, { amount: event.target.value })} inputMode="decimal" placeholder="lei" /><input aria-label="Produs" value={line.label} onChange={(event) => updateLine(line.id, { label: event.target.value })} placeholder="ex. fructe" />{lines.length > 1 && <button aria-label="Elimină produsul" onClick={() => setLines((current) => current.filter((entry) => entry.id !== line.id))}><Trash2 size={16} /></button>}</div>)}<small>OCR-ul propune linii editabile. Fiecare linie devine o cheltuială reală, iar totalul liniilor trebuie să fie egal cu totalul bonului.</small></section>{ocrText && <Field label="Text citit local (verifică înainte de salvare)"><textarea value={note} onChange={(event) => setNote(event.target.value)} /></Field>}{!ocrText && <Field label="Produse / notiță"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. apă, fructe, detergent" /></Field>}{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" disabled={busy} onClick={save}><Check size={17} /> Salvează bonul și cheltuielile</button></Modal>;
}

function AdvisorStudio({ data }: { data: AppData }) {
  const math = planMath(data); const forecast = planForecast(data); const balance = financialBalance(data); const [question, setQuestion] = useState(""); const [scenario, setScenario] = useState("");
  const parsedScenario = parseNaturalSpendScenario(scenario, [...expenseCategories, ...data.settings.customCategories]); const suggestions = savingSuggestions(data); const priorityAdvice = suggestions[0];
  const responseFor = (raw: string) => {
    const budgetQuestion = answerBudgetQuestion(raw, data); if (budgetQuestion) { const figure = new Intl.NumberFormat("ro-RO", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(budgetQuestion.result); const label = budgetQuestion.category ? `pentru ${budgetQuestion.category.toLocaleLowerCase("ro-RO")}` : "pentru bugetul menționat"; const source = budgetQuestion.source === "envelope" ? "plicul salvat" : budgetQuestion.source === "plan" ? "planul curent" : "suma scrisă de tine"; if (budgetQuestion.kind === "weekly-average") return `${money(budgetQuestion.amount)} este bugetul săptămânal ${label}. Media pentru o zi este ${figure} RON: ${money(budgetQuestion.amount)} ÷ 7 zile. Calculul folosește ${source} și nu modifică planul.`; if (budgetQuestion.kind === "remaining-daily") return `Până la venit sunt ${budgetQuestion.days} zile. Pentru ${label}, media prudentă este ${figure} RON pe zi: ${money(budgetQuestion.amount)} ÷ ${budgetQuestion.days} zile. Calculul folosește ${source} și nu modifică datele.`; return `Media orientativă este ${figure} RON pe zi ${label}: ${money(budgetQuestion.amount)} ÷ ${budgetQuestion.days} ${budgetQuestion.days === 1 ? "zi" : "zile"}. Calculul folosește ${source} și nu modifică planul.`; }
    const query = raw.toLowerCase(); const top = Object.entries(data.transactions.filter((item) => item.kind === "expense" && inPlanPeriod(item.date, math.plan)).reduce<Record<string, number>>((all, item) => ({ ...all, [item.category]: (all[item.category] || 0) + item.amount }), {})).sort((a, b) => b[1] - a[1])[0];
    if (query.includes("dator") || query.includes("rat")) return data.debts.length ? `Ratele lunare însumează ${money(balance.monthlyRates)}, iar datoria rămasă este ${money(balance.debtRemaining)}. Cea mai mare obligație este ${[...data.debts].sort((a, b) => b.remaining - a.remaining)[0].name}. Acestea devin cheltuieli în registru numai când confirmi plata.` : "Nu ai înregistrat datorii. Adaugă o rată dacă vrei să fie rezervată în plan.";
    if (query.includes("bilant") || query.includes("bilanț") || query.includes("sold") || query.includes("lichid")) return `Poziția lichidă netă este ${money(balance.netLiquidPosition)}: solduri utilizabile ${money(balance.liquidFunds)} minus datorii rămase ${money(balance.debtRemaining)}. Fluxul planului este ${money(balance.cashflow)}, iar economiile urmărite sunt afișate separat: ${money(balance.savingsCurrent)}.`;
    if (query.includes("progno") || query.includes("ritm") || query.includes("ajung")) return math.plan.nextPayday ? `Cheltuielile înregistrate au un ritm de ${money(forecast.paceDaily)} pe zi. Dacă ritmul se păstrează, până la ${dateText(math.planEnd || math.plan.nextPayday)} ar rămâne ${money(forecast.projectedRemaining)} după rezerve. Ritmul sigur, din planul curent, este ${money(forecast.safeDaily)} pe zi.` : "Alege data următorului venit în Plan pentru a calcula o proiecție până la salariu.";
    if (query.includes("chelt") || query.includes("mult") || query.includes("categorie")) return top ? `În perioada activă, ${top[0]} este categoria principală: ${money(top[1])}. Răspunsul folosește mișcările dintre ${dateText(math.plan.periodStart)} și ${math.planEnd ? dateText(math.planEnd) : "sfârșitul perioadei"}.` : "Nu există încă cheltuieli în perioada activă.";
    if (query.includes("plan") || query.includes("limit") || query.includes("salariu")) return `Planul are ${money(math.budget)} disponibili, ${money(math.periodExpenses)} cheltuiți și ${money(Math.max(0, math.remaining))} rămași până la următorul venit. Limita curentă este ${money(math.weekly)} pe săptămână.`;
    return priorityAdvice ? `Cea mai importantă observație acum: ${priorityAdvice.title}. ${priorityAdvice.detail} Pas sugerat: ${priorityAdvice.nextStep || "verifică planul și jurnalul"}.` : `În perioada activă sunt ${math.days} zile, cu ${money(Math.max(0, math.remaining))} disponibili. Întreabă despre ritm, plan, cheltuieli, datorii sau obiective.`;
  };
  const [answer, setAnswer] = useState(() => responseFor("")); const scenarioAmount = parsedScenario.amount || parseRomanianAmount(scenario); const scenarioRemaining = forecast.projectedRemaining - scenarioAmount;
  const ask = (value = question) => { setQuestion(value); setAnswer(responseFor(value)); };
  const runScenario = () => { if (scenarioAmount <= 0) return setAnswer("Am identificat eventual categoria, dar nu și o sumă. Spune, de exemplu: „Dacă plătesc 120 lei pe taxi mâine”. Simularea nu adaugă nicio mișcare în registru."); const when = parsedScenario.timing === "nespecificat" ? "" : ` ${parsedScenario.timing}`; const category = parsedScenario.category ? ` pentru ${parsedScenario.category.toLocaleLowerCase("ro-RO")}` : ""; const savingHint = suggestions.find((item) => item.id === "category"); setAnswer(`Pentru o cheltuială de ${money(scenarioAmount)}${category}${when}, proiecția până la venit devine ${money(scenarioRemaining)}. ${scenarioRemaining < 0 ? `Ar lipsi ${money(Math.abs(scenarioRemaining))}; revizuiește o cheltuială flexibilă înainte de plată.` : `Rămâne o marjă estimată de ${money(scenarioRemaining)}.`}${savingHint ? ` Observație: ${savingHint.detail}` : ""}`); };
  return <div className="bf-advisor-studio"><section className="bf-advisor-hero"><div className="bf-assistant-symbol"><Bot size={22} /></div><p className="bf-kicker">ASISTENT DE DECIZIE LOCAL</p><h2>Ce se întâmplă dacă păstrați ritmul?</h2><p>Folosește planul, registrul, bilanțul și scadențele de pe acest telefon. Nu trimite date financiare către un serviciu extern.</p><div className="bf-advisor-metrics"><span><small>Ritm actual</small><b>{money(forecast.paceDaily)}/zi</b></span><span><small>Ritm sigur</small><b>{money(forecast.safeDaily)}/zi</b></span><span><small>La venit</small><b className={forecast.projectedRemaining < 0 ? "risk" : ""}>{money(forecast.projectedRemaining)}</b></span></div></section><section className="bf-scenario-card bf-natural-scenario"><div><p className="bf-kicker">SIMULATOR CONVERSAȚIONAL</p><h3>Descrie cheltuiala în cuvintele tale</h3><p>Exemplu: „Dacă plătesc 120 lei pe taxi mâine”. Interpretarea rămâne locală și nu salvează nimic.</p></div><textarea value={scenario} onChange={(event) => setScenario(event.target.value)} placeholder="Scrie o cheltuială propusă…" aria-label="Scenariu de cheltuială în limbaj natural" rows={2} /><p className="bf-scenario-preview" aria-live="polite">{parsedScenario.understood ? <>Am înțeles: <b>{money(parsedScenario.amount)}</b>{parsedScenario.category ? ` · ${parsedScenario.category}` : ""}{parsedScenario.timing !== "nespecificat" ? ` · ${parsedScenario.timing}` : ""}.</> : "Adaugă suma în lei; categoria și momentul sunt opționale."}</p><div className="bf-scenario-actions"><button onClick={() => setScenario("Dacă plătesc 120 lei pe taxi mâine")}>Exemplu taxi</button><button onClick={() => setScenario("Dacă cheltuiesc 80 lei la restaurant azi")}>Exemplu restaurant</button><button className="bf-primary" onClick={runScenario}>Simulează</button></div></section><section className="bf-saving-suggestions"><div><p className="bf-kicker">RECOMANDĂRI PERSONALIZATE</p><h3>Ce arată istoricul și bilanțul tău</h3><p className="bf-advice-intro">Fiecare observație are o bază din registru și sugerează un pas de planificare; nu schimbă nicio sumă automat.</p></div>{suggestions.map((suggestion) => <article key={suggestion.id} className={suggestion.tone}><span>{suggestion.tone === "risk" ? "!" : suggestion.tone === "watch" ? "≈" : "✓"}</span><div><b>{suggestion.title}</b><p>{suggestion.detail}</p>{suggestion.basis && <small className="bf-advice-basis">Bazat pe: {suggestion.basis}</small>}{suggestion.nextStep && <small className="bf-advice-next">Pas sugerat: {suggestion.nextStep}</small>}</div>{suggestion.potential !== undefined && <em>{money(suggestion.potential)}</em>}</article>)}</section><section className="bf-advisor-answer" aria-live="polite"><p className="bf-kicker">RĂSPUNS EXPLICABIL</p><p>{answer}</p></section><div className="bf-advisor-prompts"><button onClick={() => ask("Care este prognoza până la salariu?")}>Prognoza până la venit</button><button onClick={() => ask("Cum arată bilanțul meu?")}>Bilanțul meu</button><button onClick={() => ask("Pe ce cheltuim cel mai mult?")}>Categoria principală</button><button onClick={() => ask("Care sunt ratele și datoriile?")}>Rate și datorii</button></div><div className="bf-advisor-question"><input value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => event.key === "Enter" && ask()} placeholder="ex. Ajungem la salariu cu ritmul actual?" /><button aria-label="Analizează" onClick={() => ask()}><Send size={18} /></button></div><small className="bf-advisor-note">Sunt AI, nu consultant financiar autorizat: această analiză se bazează pe datele introduse, nu este garantată și nu face tranzacții. O funcție AI externă ar necesita acord explicit și o infrastructură separată, securizată.</small></div>;
}

function MoreView({ tab, setTab, data, onChange, onAddReceipt, onDeleteReceipt, onOpenDebt, onOpenSaving }: { tab: MoreView; setTab: (value: MoreView) => void; data: AppData; onChange: (value: AppData) => void; onAddReceipt: () => void; onDeleteReceipt: (id: string) => void; onOpenDebt: () => void; onOpenSaving: () => void }) {
  const isCollaborative = data.settings.members.length > 1; const tabs: { id: MoreView; label: string; icon: typeof SlidersHorizontal }[] = [{ id: "overview", label: "Instrumente", icon: MoreHorizontal }, { id: "debts", label: "Datorii", icon: BellRing }, { id: "savings", label: "Economii", icon: PiggyBank }, { id: "receipts", label: "Bonuri", icon: ReceiptText }, { id: "recurring", label: "Scadențe", icon: CalendarDays }, { id: "reports", label: "Statistici", icon: LayoutDashboard }, { id: "assistant", label: "Asistent", icon: Bot }, { id: "settings", label: "Setări", icon: Settings }, { id: "sync", label: "Sync", icon: Cloud }, { id: "guide", label: "Ghid", icon: BookOpen }];
  const setSettings = (patch: Partial<AppData["settings"]>) => onChange({ ...data, settings: { ...data.settings, ...patch } });
  const content = () => {
    if (tab === "overview") return <div className="bf-more-grid"><button onClick={onOpenDebt}><BellRing size={20} /><b>Datorii</b><span>{data.debts.length} active</span></button><button onClick={onOpenSaving}><PiggyBank size={20} /><b>Economii</b><span>{data.savings.length} obiective</span></button><button onClick={onAddReceipt}><Camera size={20} /><b>Bonuri</b><span>{data.receipts.length} salvate</span></button><button onClick={() => setTab("recurring")}><CalendarClock size={20} /><b>Scadențe</b><span>{data.recurring.length} programate</span></button><button onClick={() => setTab("assistant")}><Bot size={20} /><b>Asistent</b><span>explică datele</span></button><button onClick={() => setTab("settings")}><Settings size={20} /><b>{isCollaborative ? "Setări familie" : "Setări profil"}</b><span>{isCollaborative ? "membri și surse" : "surse și categorii"}</span></button><button onClick={() => setTab("sync")}><Cloud size={20} /><b>Sincronizare</b><span>{isCollaborative ? "spațiu conectat" : "opțională între telefoane"}</span></button><button onClick={() => setTab("guide")}><BookOpen size={20} /><b>Manual</b><span>configurare și utilizare</span></button></div>;
    if (tab === "debts") return <div className="bf-more-list">{data.debts.map((debt) => <article key={debt.id}><span><b>{debt.name}</b><small>{debt.due}</small></span><strong>{money(debt.remaining)}</strong><em>{money(debt.monthly)}/lună</em></article>)}{!data.debts.length && <div className="bf-empty-state slim"><BellRing size={23} /><h2>Nicio datorie</h2><button className="bf-primary" onClick={onOpenDebt}><Plus size={16} /> Adaugă datorie</button></div>}</div>;
    if (tab === "savings") return <div className="bf-more-list">{data.savings.map((saving) => <article key={saving.id}><span><b>{saving.name}</b><small>{saving.due}</small></span><strong>{money(saving.current)}</strong><BudgetBar used={saving.current} total={saving.target} tone="gold" /></article>)}{!data.savings.length && <div className="bf-empty-state slim"><PiggyBank size={23} /><h2>Niciun obiectiv</h2><button className="bf-primary" onClick={onOpenSaving}><Plus size={16} /> Creează obiectiv</button></div>}</div>;
    if (tab === "receipts") return <div><button className="bf-primary bf-inline-add" onClick={onAddReceipt}><Camera size={17} /> Adaugă bon</button><div className="bf-receipt-list">{data.receipts.map((receipt) => <article key={receipt.id}>{receipt.imageData ? <img src={receipt.imageData} alt={`Bon ${receipt.vendor}`} /> : <span className="bf-receipt-icon"><ReceiptText size={21} /></span>}<div><b>{receipt.vendor}</b><small>{dateText(receipt.date)} · {receipt.lines?.length || 1} categorie{(receipt.lines?.length || 1) === 1 ? "" : "i"}</small><p>{receipt.lines?.map((line) => `${line.category}: ${money(line.amount)}`).join(" · ") || receipt.note || "Fără detalii"}</p>{receipt.imageData2 && <small>Bon în două fotografii</small>}</div><strong>{money(receipt.amount)}</strong><button aria-label={`Șterge bonul ${receipt.vendor}`} onClick={() => onDeleteReceipt(receipt.id)}><Trash2 size={16} /></button></article>)}{!data.receipts.length && <div className="bf-empty-state slim"><ReceiptText size={23} /><h2>Niciun bon</h2><p>Un bon poate avea două poze și mai multe categorii; fiecare categorie creează o cheltuială legată de același bon.</p></div>}</div></div>;
    if (tab === "recurring") return <Suspense fallback={<div className="bf-lazy-panel">Pregătim scadențele…</div>}><RecurringPanel data={data} onChange={onChange} /></Suspense>;
    if (tab === "reports") return <Suspense fallback={<div className="bf-lazy-panel">Pregătim statisticile…</div>}><ReportsPanel data={data} /></Suspense>;
    if (tab === "assistant") return <Suspense fallback={<div className="bf-lazy-panel">Pregătim asistentul…</div>}><AdvisorPanel data={data} /></Suspense>;
    if (tab === "settings") return <SettingsPanel data={data} onChange={onChange} onReset={() => window.confirm("Ștergi toate datele locale de pe acest dispozitiv?") && onChange(createEmptyAppData())} />;
    if (tab === "guide") return <FamilyGuide />;
    return <SyncPanel data={data} onChange={onChange} />;
  };
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">MAI MULT</p><h1>Instrumentele <em>{isCollaborative ? "comune." : "tale."}</em></h1></div></header><div className="bf-more-tabs">{tabs.map((item) => { const Icon = item.icon; return <button key={item.id} className={tab === item.id ? "active" : ""} onClick={() => setTab(item.id)}><Icon size={16} /> {item.label}</button>; })}</div>{content()}</div>;
}

function SettingsPanel({ data, onChange, onReset }: { data: AppData; onChange: (value: AppData) => void; onReset: () => void }) {
  const [member, setMember] = useState(""); const [source, setSource] = useState(""); const [kind, setKind] = useState<PaymentKind>("card"); const [owner, setOwner] = useState(data.settings.members[0]?.id || ""); const [category, setCategory] = useState("");
  const settings = data.settings; const change = (patch: Partial<typeof settings>) => onChange({ ...data, settings: { ...settings, ...patch } });
  const addMember = () => { if (!member.trim()) return; if (settings.members.some((item) => item.name.toLowerCase() === member.trim().toLowerCase())) return; change({ members: [...settings.members, { id: newId("member"), name: member.trim() }] }); setMember(""); };
  const addSource = () => { if (!source.trim()) return; change({ paymentSources: [...settings.paymentSources, { id: newId("source"), name: source.trim(), kind, memberId: kind === "transfer" ? undefined : owner, openingBalance: 0 }] }); setSource(""); };
  return <div className="bf-settings"><section><p className="bf-kicker">FAMILIE</p><Field label="Numele familiei"><input value={settings.familyName} onChange={(event) => change({ familyName: event.target.value })} /></Field><Field label="Numele tău"><input value={settings.memberName} onChange={(event) => change({ memberName: event.target.value })} /></Field><Field label="Cod local de familie" hint="Codul ajută la verificarea exportului manual."><input value={settings.familyCode} onChange={(event) => change({ familyCode: event.target.value.toUpperCase() })} /><button className="bf-link-button" onClick={() => change({ familyCode: createFamilyCode() })}><RotateCcw size={14} /> Cod nou</button></Field></section><section><p className="bf-kicker">MEMBRI</p><div className="bf-chip-list">{settings.members.map((item) => <span key={item.id}>{item.name}{settings.members.length > 1 && <button onClick={() => change({ members: settings.members.filter((memberItem) => memberItem.id !== item.id) })}><X size={14} /></button>}</span>)}</div><div className="bf-mini-form"><input value={member} onChange={(event) => setMember(event.target.value)} placeholder="ex. Soția" /><button onClick={addMember}>Adaugă</button></div></section><section><p className="bf-kicker">SURSE ȘI SOLD INITIAL</p>{settings.paymentSources.map((item) => <div className="bf-source-edit" key={item.id}><span><b>{item.name}</b><small>{sourceKindName[item.kind]} · {settings.members.find((memberItem) => memberItem.id === item.memberId)?.name || "Comun"}</small></span><label><small>Sold inițial</small><input inputMode="decimal" value={String(item.openingBalance)} onChange={(event) => change({ paymentSources: settings.paymentSources.map((sourceItem) => sourceItem.id === item.id ? { ...sourceItem, openingBalance: Math.max(0, parseRomanianAmount(event.target.value)) } : sourceItem) })} /></label><strong>{money(sourceBalance(data, item.id))}</strong></div>)}<div className="bf-source-builder"><input value={source} onChange={(event) => setSource(event.target.value)} placeholder="ex. Card soție" /><select value={kind} onChange={(event) => setKind(event.target.value as PaymentKind)}>{Object.entries(sourceKindName).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select><select value={owner} disabled={kind === "transfer"} onChange={(event) => setOwner(event.target.value)}>{settings.members.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={addSource}>Adaugă</button></div></section><section><p className="bf-kicker">CATEGORII PROPRII</p><div className="bf-chip-list">{settings.customCategories.map((item) => <span key={item}>{item}<button onClick={() => change({ customCategories: settings.customCategories.filter((categoryItem) => categoryItem !== item) })}><X size={14} /></button></span>)}</div><div className="bf-mini-form"><input value={category} onChange={(event) => setCategory(event.target.value)} placeholder="ex. Taxi" /><button onClick={() => { if (category.trim() && !settings.customCategories.includes(category.trim())) { change({ customCategories: [...settings.customCategories, category.trim()] }); setCategory(""); } }}>Adaugă</button></div></section><section className="bf-danger"><p className="bf-kicker">RESETARE</p><h2>Începe curat pe acest dispozitiv</h2><p>Șterge numai datele locale. O copie sincronizată sau exportată nu este afectată.</p><button onClick={onReset}><Trash2 size={16} /> Resetează datele locale</button></section></div>;
}

function SyncPanel({ data, onChange }: { data: AppData; onChange: (value: AppData) => void }) {
  const [token, setToken] = useState(""); const [password, setPassword] = useState(""); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const [connected, setConnected] = useState(false); const [lastSync, setLastSync] = useState(""); const shaRef = useRef<string | undefined>(undefined); const dataRef = useRef(data); dataRef.current = data;
  const owner = "Balty1991"; const repo = "buget-familie-date"; const path = "family-sync.enc.json";
  const check = () => { if (!token.trim()) throw new Error("Introdu un token GitHub limitat la repo-ul privat de date."); if (password.length < 12) throw new Error("Parola de criptare trebuie să aibă cel puțin 12 caractere."); };
  const portable = (value: AppData) => ({ ...value, receipts: value.receipts.map(({ imageData: _one, imageData2: _two, ...rest }) => rest) });
  const retainLocalReceiptImages = (value: AppData): AppData => ({ ...value, receipts: value.receipts.map((receipt) => { const local = dataRef.current.receipts.find((item) => item.id === receipt.id); return { ...receipt, imageData: local?.imageData, imageData2: local?.imageData2 }; }) });
  const syncNow = async (announce = true): Promise<boolean> => {
    check(); setBusy(true);
    try {
      const remote = await getRemotePackage({ token, owner, repo, path });
      const remoteData = remote ? normalizeAppData(await decryptFamilyData(remote.envelope, password)) : createEmptyAppData();
      const merged = retainLocalReceiptImages(remote ? mergeFamilyData(dataRef.current, remoteData) : dataRef.current);
      if (remote && JSON.stringify(portable(merged)) === JSON.stringify(portable(remoteData))) {
        shaRef.current = remote.sha; onChange(merged); setLastSync(new Date().toISOString()); if (announce) setNotice("Familia era deja actualizată. Nu a fost creat un commit nou."); return true;
      }
      const envelope = await encryptFamilyData(portable(merged), password);
      const nextSha = await saveRemotePackage({ token, owner, repo, path, envelope, sha: remote?.sha });
      shaRef.current = nextSha; onChange(merged); setLastSync(new Date().toISOString()); if (announce) setNotice("Familia este actualizată. Modificările au fost reunite și criptate."); return true;
    } catch (error) { setNotice(error instanceof Error ? error.message : "Nu s-a putut actualiza familia."); return false; } finally { setBusy(false); }
  };
  const connect = async () => { if (!token.trim() || password.length < 12) return setNotice("Introdu tokenul repo-ului privat și o parolă de cel puțin 12 caractere."); if (await syncNow(false)) { setConnected(true); setNotice("Sesiunea familiei este activă. Verificăm actualizări la aproximativ 30 de secunde cât aplicația rămâne deschisă."); } };
  const pull = async () => { try { check(); setBusy(true); const remote = await getRemotePackage({ token, owner, repo, path }); if (!remote) return setNotice("Nu există încă o copie în repo-ul privat."); const restored = normalizeAppData(await decryptFamilyData(remote.envelope, password)); onChange(retainLocalReceiptImages(mergeFamilyData(dataRef.current, restored))); shaRef.current = remote.sha; setLastSync(new Date().toISOString()); setNotice("Actualizările familiei au fost reunite local, fără a șterge intrările acestei sesiuni."); } catch (error) { setNotice(error instanceof Error ? error.message : "Nu s-a putut descărca copia."); } finally { setBusy(false); } };
  useEffect(() => { if (!connected) return; const interval = window.setInterval(() => { void syncNow(false); }, 30_000); return () => window.clearInterval(interval); }, [connected, token, password]);
  return <div className="bf-sync"><div className="bf-sync-hero"><Users size={25} /><p className="bf-kicker">FAMILIE CONECTATĂ</p><h2>{connected ? "Sesiunea familiei este activă." : "Sincronizare criptată între telefoane."}</h2><p>În repo-ul privat ajunge doar un pachet AES-GCM. Pozele bonurilor și parola rămân pe telefon.</p></div><section className="bf-sync-session"><p className="bf-kicker">{connected ? "CONECTAT" : "CONECTEAZĂ FAMILIA"}</p>{connected ? <><p><b>Actualizare prudentă la aproximativ 30 secunde</b><br />Sesiunea funcționează cât aplicația este deschisă. Tokenul rămâne doar în memorie.</p><div className="bf-sync-actions"><button className="bf-secondary" disabled={busy} onClick={() => void pull()}><Download size={16} /> Verifică acum</button><button className="bf-primary" disabled={busy} onClick={() => void syncNow()}><Cloud size={16} /> Sincronizează acum</button></div><button className="bf-link-button" onClick={() => { setConnected(false); setToken(""); setPassword(""); setNotice("Sesiunea a fost închisă pe acest telefon."); }}>Închide sesiunea acestui telefon</button></> : <><Field label="Token GitHub limitat"><input type="password" value={token} onChange={(event) => setToken(event.target.value)} placeholder="github_pat_..." autoComplete="off" /></Field><Field label="Parola de criptare a familiei"><input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="minimum 12 caractere" autoComplete="new-password" /></Field><p className="bf-helper">Pe fiecare telefon se folosește un token fine-grained separat, cu <b>Contents: Read and write</b> doar pentru repo-ul privat <b>{repo}</b>. Tokenul și parola nu se salvează.</p><button className="bf-primary full" disabled={busy} onClick={() => void connect()}><Users size={17} /> Conectează acest telefon</button></>}</section>{lastSync && <p className="bf-helper">Ultima actualizare: {new Intl.DateTimeFormat("ro-RO", { hour: "2-digit", minute: "2-digit", second: "2-digit" }).format(new Date(lastSync))}</p>}{notice && <p className="bf-notice" role="status"><Check size={15} /> {notice}</p>}</div>;
}

function FamilyGuide() { return <div className="bf-guide"><section className="bf-guide-hero"><BookOpen size={25} /><p className="bf-kicker">MANUAL RAPID</p><h2>Doar tu sau împreună.</h2><p>Poți urmări banii proprii de la prima deschidere. Membrii și conectarea telefoanelor sunt opționale.</p></section><section><p className="bf-kicker">1. PORNEȘTE CU TINE</p><h3>Configurează profilul și banii reali</h3><p>În <b>Setări familie</b>, păstrează un singur membru pentru monitorizare personală sau adaugă mai mulți membri când aveți un buget comun. Configurează sursele și soldurile inițiale, apoi creează planul până la următorul venit.</p></section><section><p className="bf-kicker">2. CONECTEAZĂ OPȚIONAL</p><h3>Folosește repo-ul privat, nu repo-ul aplicației</h3><p>Dacă vrei același registru pe mai multe telefoane, administratorul creează tokenuri fine-grained distincte cu <b>Contents: Read and write</b> numai pentru <b>buget-familie-date</b>. În <b>Mai mult → Sincronizare</b>, fiecare telefon folosește tokenul propriu și aceeași parolă de grup.</p></section><section><p className="bf-kicker">3. LUCREAZĂ ZILNIC</p><h3>Înregistrează, verifică, decide</h3><p>Adaugă mișcările la momentul plății. Pentru cumpărături mixte, un bon poate avea două poze și mai multe categorii. Verifică zilnic punctul de decizie și confirmă scadențele când sunt plătite.</p></section><section><p className="bf-kicker">4. PROTEJEAZĂ DATELE</p><h3>Nu trimite parole sau tokenuri</h3><p>Tokenul și parola nu sunt salvate de aplicație. Nu le pune în conversații, bonuri sau capturi de ecran. Dacă un telefon se pierde, revocă tokenul acelui telefon în GitHub și creează unul nou.</p></section></div>; }

export default function Home() {
  const [data, setData] = useState<AppData>(() => { try { const raw = window.localStorage.getItem(STORE_KEY) || window.localStorage.getItem(LEGACY_KEY); return raw ? normalizeAppData(JSON.parse(raw)) : createEmptyAppData(); } catch { return createEmptyAppData(); } });
  const [view, setView] = useState<MainView>("home"); const [more, setMore] = useState<MoreView>("overview"); const [modal, setModal] = useState<"transaction" | "receipt" | "debt" | "saving" | "debt-payment" | null>(null); const [editTx, setEditTx] = useState<Transaction>(); const [editGoal, setEditGoal] = useState<Debt | SavingsGoal>(); const [themePickerOpen, setThemePickerOpen] = useState(false); const [theme, setTheme] = useState<ThemeId>(() => { const saved = window.localStorage.getItem("buget-familie:theme"); return saved === "dark" ? "forest" : themeOptions.some((item) => item.id === saved) ? saved as ThemeId : "ivory"; });
  useEffect(() => { window.localStorage.setItem(STORE_KEY, JSON.stringify(data)); }, [data]); useEffect(() => { setData((current) => autoPostDueRecurring(current)); }, []); useEffect(() => { document.documentElement.classList.remove("theme-ivory", "theme-forest", "theme-midnight", "theme-copper"); document.documentElement.classList.add(`theme-${theme}`); document.documentElement.classList.toggle("dark", theme !== "ivory"); window.localStorage.setItem("buget-familie:theme", theme); }, [theme]); useEffect(() => { window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior }); }, [view, more]);
  const update = (fn: (current: AppData) => AppData) => setData((current) => fn(current));
  const saveTx = (item: Transaction) => update((current) => { const stamped = { ...item, updatedAt: new Date().toISOString() }; return { ...current, transactions: current.transactions.some((entry) => entry.id === item.id) ? current.transactions.map((entry) => entry.id === item.id ? stamped : entry) : [stamped, ...current.transactions] }; });
  const saveDebt = (item: Debt | SavingsGoal) => update((current) => { const stamped = { ...item, updatedAt: new Date().toISOString() } as Debt; return { ...current, debts: current.debts.some((entry) => entry.id === item.id) ? current.debts.map((entry) => entry.id === item.id ? stamped : entry) : [...current.debts, stamped] }; });
  const saveSaving = (item: Debt | SavingsGoal) => update((current) => { const stamped = { ...item, updatedAt: new Date().toISOString() } as SavingsGoal; return { ...current, savings: current.savings.some((entry) => entry.id === item.id) ? current.savings.map((entry) => entry.id === item.id ? stamped : entry) : [...current.savings, stamped] }; });
  const saveReceipt = (item: Receipt) => update((current) => { const member = current.settings.members.find((entry) => entry.id === item.memberId) || current.settings.members[0]; const source = current.settings.paymentSources.find((entry) => entry.id === item.sourceId) || current.settings.paymentSources[0]; const lines = item.lines?.length ? item.lines : [{ id: "whole", category: item.category, amount: item.amount }]; const transactionIds = lines.map((line) => `receipt-tx-${item.id}-${line.id}`); const receipt = { ...item, linkedTransactionId: transactionIds[0], linkedTransactionIds: transactionIds }; const transactions: Transaction[] = lines.map((line, index) => ({ id: transactionIds[index], receiptId: item.id, title: `Bon — ${item.vendor}${line.label ? ` · ${line.label}` : ""}`, amount: line.amount, kind: "expense", category: line.category, sourceId: source?.id, source: source?.name || "Bon", memberId: member?.id, person: member?.name || current.settings.memberName, date: item.date, note: item.note, createdAt: new Date().toISOString() })); const formerIds = current.receipts.find((entry) => entry.id === item.id)?.linkedTransactionIds || [item.linkedTransactionId, `receipt-tx-${item.id}`].filter((value): value is string => Boolean(value)); return { ...current, receipts: [receipt, ...current.receipts.filter((entry) => entry.id !== item.id)], transactions: [...transactions, ...current.transactions.filter((entry) => !formerIds.includes(entry.id) && entry.receiptId !== item.id)] }; });
  const deleteReceipt = (id: string) => update((current) => { const receipt = current.receipts.find((item) => item.id === id); const linked = receipt?.linkedTransactionIds || [receipt?.linkedTransactionId, `receipt-tx-${id}`].filter((value): value is string => Boolean(value)); const now = new Date().toISOString(); return { ...current, receipts: current.receipts.filter((item) => item.id !== id), transactions: current.transactions.filter((item) => !linked.includes(item.id) && item.receiptId !== id), deleted: [...current.deleted, { entity: "receipts" as const, id, deletedAt: now }, ...linked.map((transactionId) => ({ entity: "transactions" as const, id: transactionId, deletedAt: now }))].slice(-500) }; });
  const openTx = (item?: Transaction) => { setEditTx(item); setModal("transaction"); };
  const nav = [{ id: "home" as MainView, label: "Acasă", icon: LayoutDashboard }, { id: "journal" as MainView, label: "Jurnal", icon: WalletCards }, { id: "plan" as MainView, label: "Plan", icon: Goal }, { id: "objectives" as MainView, label: "Obiective", icon: PiggyBank }, { id: "more" as MainView, label: "Mai mult", icon: MoreHorizontal }];
  const current = () => { if (view === "journal") return <JournalView data={data} onAdd={() => openTx()} onEdit={openTx} onDelete={(id) => update((currentData) => ({ ...currentData, transactions: currentData.transactions.filter((item) => item.id !== id), receipts: currentData.receipts.filter((receipt) => receipt.linkedTransactionId !== id), deleted: [...currentData.deleted, { entity: "transactions" as const, id, deletedAt: new Date().toISOString() }].slice(-500) }))} />; if (view === "plan") return <PlanView data={data} onChange={setData} />; if (view === "objectives") return <ObjectivesView data={data} onEditDebt={(item) => { setEditGoal(item); setModal("debt"); }} onEditSaving={(item) => { setEditGoal(item); setModal("saving"); }} onPayDebt={(item) => { setEditGoal(item); setModal("debt-payment"); }} onDeleteDebt={(id) => window.confirm("Ștergi această datorie? Acțiunea poate fi sincronizată și pe celelalte dispozitive.") && update((currentData) => ({ ...currentData, debts: currentData.debts.filter((item) => item.id !== id), deleted: [...currentData.deleted, { entity: "debts" as const, id, deletedAt: new Date().toISOString() }].slice(-500) }))} onDeleteSaving={(id) => window.confirm("Ștergi acest obiectiv de economisire? Acțiunea poate fi sincronizată și pe celelalte dispozitive.") && update((currentData) => ({ ...currentData, savings: currentData.savings.filter((item) => item.id !== id), deleted: [...currentData.deleted, { entity: "savings" as const, id, deletedAt: new Date().toISOString() }].slice(-500) }))} openDebt={() => { setEditGoal(undefined); setModal("debt"); }} openSaving={() => { setEditGoal(undefined); setModal("saving"); }} />; if (view === "more") return <MoreView tab={more} setTab={setMore} data={data} onChange={setData} onAddReceipt={() => setModal("receipt")} onDeleteReceipt={deleteReceipt} onOpenDebt={() => { setEditGoal(undefined); setModal("debt"); }} onOpenSaving={() => { setEditGoal(undefined); setModal("saving"); }} />; return <HomeView data={data} onAdd={() => openTx()} onGo={(next, tab) => { setView(next); if (tab) setMore(tab); }} />; };
  return <div className="bf-app">
    <header className="bf-appbar"><button className="bf-brand" onClick={() => setView("home")}><span className="bf-brand-mark bf-logo-3d" aria-label="Monograma Buget Familie"><span className="bf-logo-roof" /><span className="bf-logo-core"><span className="bf-logo-letter bf-logo-letter-b">B</span><span className="bf-logo-letter bf-logo-letter-f">F</span></span></span><b>Buget <i>Familie</i></b></button><nav aria-label="Navigație principală">{nav.map((item) => { const Icon = item.icon; return <button key={item.id} className={view === item.id ? "active" : ""} onClick={() => setView(item.id)}><Icon size={17} /><span>{item.label}</span></button>; })}</nav><button className="bf-theme" aria-label="Alege tema aplicației" title={`Tema activă: ${themeOptions.find((item) => item.id === theme)?.name}`} onClick={() => setThemePickerOpen(true)}><Palette size={18} /></button></header>
    <main>{current()}</main>
    <nav className="bf-mobile-nav" aria-label="Navigație mobilă">{nav.map((item) => { const Icon = item.icon; return <button key={item.id} className={view === item.id ? "active" : ""} onClick={() => setView(item.id)}><Icon size={20} /><span>{item.label}</span></button>; })}</nav>
    {themePickerOpen && <ThemePicker theme={theme} onChange={setTheme} onClose={() => setThemePickerOpen(false)} />}
    {modal === "transaction" && <TransactionForm data={data} initial={editTx} onSave={saveTx} onClose={() => { setModal(null); setEditTx(undefined); }} />}
    {modal === "receipt" && <ReceiptForm data={data} onSave={saveReceipt} onClose={() => setModal(null)} />}
    {modal === "debt" && <GoalForm data={data} type="debt" item={editGoal} onSave={saveDebt} onClose={() => { setModal(null); setEditGoal(undefined); }} />}
    {modal === "saving" && <GoalForm data={data} type="saving" item={editGoal} onSave={saveSaving} onClose={() => { setModal(null); setEditGoal(undefined); }} />}
    {modal === "debt-payment" && editGoal && "remaining" in editGoal && <DebtPaymentForm data={data} debt={editGoal} onSave={setData} onClose={() => { setModal(null); setEditGoal(undefined); }} />}
  </div>;
}
function PlanView({ data, onChange }: { data: AppData; onChange: (data: AppData) => void }) {
  const plan = data.settings.salaryPlan; const [mode, setMode] = useState<"member" | "category">("category"); const [target, setTarget] = useState(expenseCategories[0]); const [allocationMemberId, setAllocationMemberId] = useState(""); const [sourceId, setSourceId] = useState(data.settings.paymentSources[0]?.id || ""); const [amount, setAmount] = useState(""); const [note, setNote] = useState(""); const maths = planMath(data);
  const updatePlan = (patch: Partial<typeof plan>) => onChange({ ...data, settings: { ...data.settings, salaryPlan: { ...plan, ...patch, updatedAt: new Date().toISOString() } } });
  const baseCategories = [...expenseCategories, ...data.settings.customCategories]; const targets = mode === "category" ? baseCategories : data.settings.members.map((item) => item.id); const envelopes = plan.allocations.map((item) => ({ item, budget: allocationBudget(data, item), spent: allocationSpent(data, item) }));
  const addEnvelope = () => { const numeric = parseRomanianAmount(amount); const source = data.settings.paymentSources.find((item) => item.id === sourceId); if (!numeric || !source) return; const member = mode === "category" ? data.settings.members.find((item) => item.id === allocationMemberId) : data.settings.members.find((item) => item.id === target); const category = mode === "category" ? target : undefined; updatePlan({ allocations: [...plan.allocations, { id: newId("allocation"), label: category ? `${category}${member ? ` · ${member.name}` : ""}` : member?.name || "Membru", amount: numeric, category, memberId: member?.id, sourceId: source.id, note: note.trim() || undefined }] }); setAmount(""); setNote(""); };
  const updateEstimatedPayday = (nextPayday: string) => updatePlan({ nextPayday, earliestPayday: plan.earliestPayday && plan.earliestPayday <= nextPayday ? plan.earliestPayday : undefined });
  return <div className="bf-page"><header className="bf-topline compact"><div><p className="bf-kicker">PLAN PÂNĂ LA URMĂTORUL VENIT</p><h1>Fă loc banilor <em>înainte de cheltuială.</em></h1></div></header><section className="bf-plan-hero"><div><p>Disponibil în această perioadă</p><strong>{money(Math.max(0, maths.remaining))}</strong><span>{maths.days} zile · {maths.weeks} săptămâni · {money(maths.weekly)} / săptămână{plan.earliestPayday ? ` · calcul prudent până la ${dateText(maths.planEnd || plan.nextPayday)}` : ""}</span></div><div className="bf-plan-hero-data"><span>Buget <b>{money(maths.budget)}</b></span><span>Cheltuit <b>{money(maths.periodExpenses)}</b></span><span>Surse <b>{money(maths.availableSources)}</b></span></div></section><section className="bf-period-card"><div className="bf-section-heading"><div><p className="bf-kicker">1. PERIOADA</p><h2>Când intră următorii bani?</h2></div><CalendarDays size={19} /></div><div className="bf-form-grid"><Field label="Începe la"><input type="date" value={plan.periodStart} onChange={(event) => updatePlan({ periodStart: event.target.value })} /></Field><Field label="De regulă intră la"><input type="date" min={plan.periodStart} value={plan.nextPayday} onChange={(event) => updateEstimatedPayday(event.target.value)} /></Field><Field label="Poate intra cel mai devreme la" hint="Planul calculează prudent până la această dată."><input type="date" min={plan.periodStart} max={plan.nextPayday || undefined} value={plan.earliestPayday || ""} onChange={(event) => updatePlan({ earliestPayday: event.target.value || undefined })} /></Field><Field label="Limită totală"><input value={plan.totalLimit ? String(plan.totalLimit) : ""} onChange={(event) => updatePlan({ totalLimit: Math.max(0, parseRomanianAmount(event.target.value)) })} inputMode="decimal" placeholder={money(maths.availableSources)} /></Field><Field label="Limită săptămânală"><input value={plan.weeklyLimit ? String(plan.weeklyLimit) : ""} onChange={(event) => updatePlan({ weeklyLimit: Math.max(0, parseRomanianAmount(event.target.value)) })} inputMode="decimal" placeholder={money(maths.weekly)} /></Field></div></section><section className="bf-period-card"><div className="bf-section-heading"><div><p className="bf-kicker">2. SURSE ACTIVE</p><h2>De unde finanțezi planul?</h2></div><WalletCards size={19} /></div><div className="bf-source-list">{data.settings.paymentSources.map((source) => { const active = !plan.sourceIds.length || plan.sourceIds.includes(source.id); return <label key={source.id} className={active ? "active" : ""}><input type="checkbox" checked={active} onChange={() => { const all = data.settings.paymentSources.map((item) => item.id); const current = plan.sourceIds.length ? plan.sourceIds : all; const next = current.includes(source.id) ? current.filter((id) => id !== source.id) : [...current, source.id]; updatePlan({ sourceIds: next.length === all.length ? [] : next }); }} /><span><b>{source.name}</b><small>{data.settings.members.find((member) => member.id === source.memberId)?.name || "Comun"}</small></span><strong>{money(sourceBalance(data, source.id))}</strong></label>; })}</div></section><section className="bf-section"><div className="bf-section-heading"><div><p className="bf-kicker">3. PLICURI DE BUGET</p><h2>Repartizează pentru categorii</h2></div></div><div className="bf-allocation-form"><select value={mode} onChange={(event) => { const next = event.target.value as typeof mode; setMode(next); setTarget(next === "category" ? expenseCategories[0] : data.settings.members[0]?.id || ""); setAllocationMemberId(""); }}><option value="category">Categorie</option><option value="member">Membru</option></select><select value={target} onChange={(event) => setTarget(event.target.value)}>{targets.map((item) => <option key={item} value={item}>{mode === "member" ? data.settings.members.find((member) => member.id === item)?.name : item}</option>)}</select>{mode === "category" && <select value={allocationMemberId} onChange={(event) => setAllocationMemberId(event.target.value)}><option value="">Plic comun (fără membru)</option>{data.settings.members.map((member) => <option key={member.id} value={member.id}>Pentru {member.name}</option>)}</select>}<select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {money(sourceBalance(data, source.id))}</option>)}</select><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="lei" /><input value={note} onChange={(event) => setNote(event.target.value)} placeholder="Detaliu opțional" /><button className="bf-primary" onClick={addEnvelope}><Plus size={17} /> Alocă</button></div><p className="bf-allocation-helper">Pentru o împărțire ca Transport 430 RON soție + 70 RON eu, creează două plicuri cu aceeași categorie, aceeași sursă și „Pentru” fiecare membru. Plicurile comune sunt alternativa implicită.</p><div className="bf-allocation-list">{envelopes.map(({ item, budget, spent }) => { const sourceName = data.settings.paymentSources.find((source) => source.id === item.sourceId)?.name; const memberName = data.settings.members.find((member) => member.id === item.memberId)?.name; return <article key={item.id}><div><b>{item.label}</b><small>{item.category ? memberName ? `Plic ${item.category} pentru ${memberName}` : "Plic de categorie comun" : "Buget personal"}{sourceName ? ` · ${sourceName}` : ""}{item.note ? ` · ${item.note}` : ""}</small></div><div><strong>{money(Math.max(0, budget - spent))}</strong><span>rămas din {money(budget)}</span></div><BudgetBar used={spent} total={budget} tone={spent > budget ? "coral" : "green"} /><button aria-label={`Șterge ${item.label}`} onClick={() => updatePlan({ allocations: plan.allocations.filter((entry) => entry.id !== item.id), transfers: plan.transfers.filter((transfer) => transfer.fromAllocationId !== item.id && transfer.toAllocationId !== item.id) })}><Trash2 size={16} /></button></article>; })}{!envelopes.length && <p className="bf-empty-inline">Adaugă plicuri pentru Transport, Alimente sau alte categorii.</p>}</div></section><EnvelopeTransferPanel data={data} onChange={onChange} /></div>;
}
